	return a, b, nil
}

func Named(a int) (x int, err error) {
	return a, errors.New("e")
}

func Var(a int, rest ...string) int {
	return a
}

func NoArgs() {}

func OnlyErr() error {
	return errors.New("x")
}

type T struct{ X int }

func (t T) Val(a string) int { return len(a) }

func (t *T) Ptr(a string) int { return len(a) }

func (t *T) NoRet() {}

type Iface interface{ Foo() }

func TakesIface(i Iface) {}

func TakesFn(f func(int) string) {}

func WithStrings(s string, t []int, m map[string]bool, ch chan int) (string, error) {
	return strings.Repeat(s, 1), nil
}

func UsesFmt(x float64) fmt.Stringer { return nil }

type Alias = T

func StructArg(s T, p *T, i Iface) {}

func Anonymous(a struct{ B int; c string }) int { return a.B }

