package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
)

func mk(names []string, vals []string) *ast.CompositeLit {
	var elts []ast.Expr
	for i := range names {
		elts = append(elts, &ast.KeyValueExpr{
			Key:   ast.NewIdent(names[i]),
			Value: ast.NewIdent(vals[i]),
		})
	}
	return &ast.CompositeLit{Elts: elts}
}

func main() {
	fset := token.NewFileSet()
	for _, n := range []int{1, 2, 3} {
		names := []string{"name", "args", "want"}[:n]
		vals := []string{"\"x\"", "args{a: 1}", "3"}[:n]
		cl := mk(names, vals)
		var buf bytes.Buffer
		printer.Fprint(&buf, fset, cl)
		fmt.Printf("=== %d elts ===\n%s\n", n, buf.String())
	}
	// parse a file and print a composite lit with positions
	src := "package p\n\nvar x = []int{\n\t1,\n\t2,\n}\n"
	f, _ := parser.ParseFile(token.NewFileSet(), "t.go", src, parser.ParseComments)
	varDecl := f.Decls[0].(*ast.GenDecl)
	vs := varDecl.Specs[0].(*ast.ValueSpec)
	var buf bytes.Buffer
	printer.Fprint(&buf, token.NewFileSet(), vs.Values[0])
	fmt.Printf("=== parsed positions ===\n%s\n", buf.String())
}
EOF
