{"command": "cd /workspace && cat > go.mod <<'EOF'
module gotests

go 1.21
EOF
mkdir -p internal/models && cat > internal/models/models.go <<'GOEOF'
// Package models holds the data structures used to describe the Go source
// that tests are generated for.
package models

import (
	"go/ast"
	"go/token"
	"strconv"
	"strings"
)

// Expression models a Go type expression.
type Expression struct {
	Value      string
	IsStar     bool
	IsVariadic bool
	IsWriter   bool
	Underlying string
}

// Field models a function parameter, result or struct field.
type Field struct {
	Name  string
	Type  *Expression
	Index int
}

// Receiver models the receiver of a method.
type Receiver struct {
	Field  *Field
	Fields []*Field
}

// TypeParam models a type parameter of a generic function or type.
type TypeParam struct {
	Name       string
	Constraint string
}

// Function models a function or method declaration.
type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	TypeParams   []*TypeParam
	Body         string
}

// Import models an import declaration.
type Import struct {
	Name string
	Path string
}

// Package models a Go package: the files that were parsed plus everything
// that is needed to render test files for it.
type Package struct {
	Name        string
	Files       []string
	Imports     []*Import
	Functions   []*Function
	TestFuncs   map[string]bool
	Types       map[string]ast.Expr
	IsTestPkg   bool
}

// basicTypes is the set of Go types that can be compared using the == operator.
var basicTypes = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"uintptr": true, "float32": true, "float64": true,
	"complex64": true, "complex128": true, "string": true, "bool": true,
}

// predeclaredTypes are the type names that are always resolvable.
var predeclaredTypes = map[string]string{
	"bool": "bool", "byte": "byte", "complex64": "complex64", "complex128": "complex128",
	"error": "interface{Error() string}", "float32": "float32", "float64": "float64",
	"int": "int", "int8": "int8", "int16": "int16", "int32": "int32", "int64": "int64",
	"rune": "rune", "string": "string", "uint": "uint", "uint8": "uint8",
	"uint16": "uint16", "uint32": "uint32", "uint64": "uint64", "uintptr": "uintptr",
	"any": "any",
}

// writerType reports whether the expression is exactly io.Writer.
func writerType(e ast.Expr) bool {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return id.Name == "io" && sel.Sel.Name == "Writer"
}

// Render renders a type expression back to Go source.  Composite types are
// rendered in a compact form that mirrors how gotests prints underlying types.
func Render(e ast.Expr) string {
	var b strings.Builder
	renderExpr(e, &b)
	return b.String()
}

func renderExpr(e ast.Expr, b *strings.Builder) {
	switch t := e.(type) {
	case nil:
		b.WriteString("invalid type")
	case *ast.Ident:
		b.WriteString(t.Name)
	case *ast.SelectorExpr:
		renderExpr(t.X, b)
		b.WriteString(".")
		b.WriteString(t.Sel.Name)
	case *ast.StarExpr:
		b.WriteString("*")
		renderExpr(t.X, b)
	case *ast.Ellipsis:
		b.WriteString("...")
		renderExpr(t.Elt, b)
	case *ast.ArrayType:
		b.WriteString("[")
		if t.Len != nil {
			b.WriteString(renderLen(t.Len))
		}
		b.WriteString("]")
		renderExpr(t.Elt, b)
	case *ast.MapType:
		b.WriteString("map[")
		renderExpr(t.Key, b)
		b.WriteString("]")
		renderExpr(t.Value, b)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			b.WriteString("chan<- ")
		case ast.RECV:
			b.WriteString("<-chan ")
		default:
			b.WriteString("chan ")
		}
		renderExpr(t.Value, b)
	case *ast.FuncType:
		b.WriteString("func(")
		renderFieldList(t.Params, b, true)
		b.WriteString(")")
		if t.Results != nil && len(t.Results.List) > 0 {
			b.WriteString(" ")
			if len(t.Results.List) == 1 && t.Results.List[0].Names == nil {
				renderExpr(t.Results.List[0].Type, b)
			} else {
				b.WriteString("(")
				renderFieldList(t.Results, b, true)
				b.WriteString(")")
			}
		}
	case *ast.StructType:
		b.WriteString("struct{")
		renderFieldList(t.Fields, b, false)
		b.WriteString("}")
	case *ast.InterfaceType:
		b.WriteString("interface{")
		renderMethodList(t.Methods, b)
		b.WriteString("}")
	case *ast.IndexExpr:
		renderExpr(t.X, b)
		b.WriteString("[")
		renderExpr(t.Index, b)
		b.WriteString("]")
	case *ast.IndexListExpr:
		renderExpr(t.X, b)
		b.WriteString("[")
		for i, idx := range t.Indices {
			if i > 0 {
				b.WriteString(", ")
			}
			renderExpr(idx, b)
		}
		b.WriteString("]")
	default:
		b.WriteString("invalid type")
	}
}

func renderLen(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.BasicLit:
		return t.Value
	case *ast.Ident:
		return t.Name
	case *ast.Ellipsis:
		return "..."
	}
	return Render(e)
}

func renderFieldList(fl *ast.FieldList, b *strings.Builder, fn bool) {
	if fl == nil {
		return
	}
	for i, f := range fl.List {
		if i > 0 {
			b.WriteString("; ")
		}
		var tag string
		if f.Tag != nil {
			tag = f.Tag.Value
		}
		if len(f.Names) == 0 {
			// Embedded field or unnamed parameter
			if fn {
				renderExpr(f.Type, b)
			} else {
				b.WriteString("invalid type")
			}
			if tag != "" {
				b.WriteString(" ")
				b.WriteString(tag)
			}
			continue
		}
		for j, n := range f.Names {
			if j > 0 {
				b.WriteString(", ")
			}
			b.WriteString(n.Name)
		}
		b.WriteString(" ")
		if ve, ok := f.Type.(*ast.Ellipsis); ok {
			b.WriteString("[]")
			renderExpr(ve.Elt, b)
		} else {
			renderExpr(f.Type, b)
		}
		if tag != "" {
			b.WriteString(" ")
			b.WriteString(tag)
		}
	}
}

func renderMethodList(fl *ast.FieldList, b *strings.Builder) {
	if fl == nil {
		return
	}
	for i, f := range fl.List {
		if i > 0 {
			b.WriteString("; ")
		}
		if len(f.Names) == 0 {
			b.WriteString("invalid type")
			continue
		}
		b.WriteString(f.Names[0].Name)
		if ft, ok := f.Type.(*ast.FuncType); ok {
			b.WriteString("(")
			renderFieldList(ft.Params, b, true)
			b.WriteString(")")
			if ft.Results != nil && len(ft.Results.List) > 0 {
				b.WriteString(" ")
				if len(ft.Results.List) == 1 && ft.Results.List[0].Names == nil {
					renderExpr(ft.Results.List[0].Type, b)
				} else {
					b.WriteString("(")
					renderFieldList(ft.Results, b, true)
					b.WriteString(")")
				}
			}
			continue
		}
		renderExpr(f.Type, b)
	}
}

// modelable reports whether the type expression can be modelled, i.e. whether
// it can be resolved to a concrete type inside the package.
func modelable(e ast.Expr) bool {
	switch t := e.(type) {
	case nil:
		return false
	case *ast.Ident:
		return true
	case *ast.StarExpr:
		return modelable(t.X)
	case *ast.Ellipsis:
		return modelable(t.Elt)
	case *ast.ArrayType:
		return t.Len == nil || modelable(t.Len) && modelable(t.Elt)
	case *ast.MapType:
		return modelable(t.Key) && modelable(t.Value)
	case *ast.ChanType:
		return modelable(t.Value)
	case *ast.FuncType:
		return modelableFields(t.Params) && modelableFields(t.Results)
	case *ast.StructType:
		return modelableFields(t.Fields)
	case *ast.InterfaceType:
		return modelableFields(t.Methods)
	case *ast.IndexExpr:
		return modelable(t.X) && modelable(t.Index)
	case *ast.IndexListExpr:
		ok := modelable(t.X)
		for _, i := range t.Indices {
			ok = ok && modelable(i)
		}
		return ok
	default:
		return false
	}
}

func modelableFields(fl *ast.FieldList) bool {
	if fl == nil {
		return true
	}
	for _, f := range fl.List {
		if !modelable(f.Type) {
			return false
		}
	}
	return true
}

// NewExpression builds the model of a type expression.
func NewExpression(e ast.Expr, isVariadic bool, types map[string]ast.Expr) *Expression {
	res := &Expression{}
	if e == nil {
		res.Value = "invalid type"
		res.Underlying = "invalid type"
		return res
	}
	var value ast.Expr
	if st, ok := e.(*ast.StarExpr); ok && !isVariadic {
		res.IsStar = true
		value = st.X
	} else if ve, ok := e.(*ast.Ellipsis); ok && isVariadic {
		value = ve.Elt
	} else {
		value = e
	}
	res.Value = Render(value)
	res.Underlying = underlying(e, types)
	if !isVariadic && writerType(e) {
		res.IsWriter = true
	}
	return res
}

// Underlying computes the underlying type of a type expression.
func Underlying(e ast.Expr, types map[string]ast.Expr) string {
	return underlying(e, types)
}

func underlying(e ast.Expr, types map[string]ast.Expr) string {
	if e == nil {
		return "invalid type"
	}
	if st, ok := e.(*ast.StarExpr); ok {
		// A single level of pointer is stripped before resolving.
		return underlyingTop(st.X, types)
	}
	if ve, ok := e.(*ast.Ellipsis); ok {
		return "[]" + underlyingTop(ve.Elt, types)
	}
	return underlyingTop(e, types)
}

func underlyingTop(e ast.Expr, types map[string]ast.Expr) string {
	if id, ok := e.(*ast.Ident); ok {
		if decl, ok := types[id.Name]; ok {
			if !modelable(decl) {
				return "invalid type"
			}
			if _, isIdent := decl.(*ast.Ident); isIdent {
				return underlyingTop(decl, types)
			}
			return underlying(decl, types)
		}
		if u, ok := predeclaredTypes[id.Name]; ok {
			return u
		}
		return ""
	}
	if !modelable(e) {
		return ""
	}
	if ix, ok := e.(*ast.IndexExpr); ok {
		return instantiateUnderlying(ix, types)
	}
	if ilx, ok := e.(*ast.IndexListExpr); ok {
		return instantiateUnderlyingList(ilx, types)
	}
	return Render(e)
}

func typeArgsOf(name string, types map[string]ast.Expr) ([]*TypeParam, bool) {
	decl, ok := types[name]
	if !ok {
		return nil, false
	}
	gt, ok := decl.(*ast.GenericTypeDecl)
	if !ok {
		return nil, false
	}
	return gt.TypeParams, true
}

func instantiateUnderlying(ix *ast.IndexExpr, types map[string]ast.Expr) string {
	id, ok := ix.X.(*ast.Ident)
	if !ok {
		return Render(ix)
	}
	tps, ok := typeArgsOf(id.Name, types)
	if !ok {
		return Render(ix)
	}
	args := []ast.Expr{ix.Index}
	return substitute(id.Name, tps, args, types)
}

func instantiateUnderlyingList(ilx *ast.IndexListExpr, types map[string]ast.Expr) string {
	id, ok := ilx.X.(*ast.Ident)
	if !ok {
		return Render(ilx)
	}
	tps, ok := typeArgsOf(id.Name, types)
	if !ok {
		return Render(ilx)
	}
	return substitute(id.Name, tps, ilx.Indices, types)
}

// substitute replaces the type parameters of a generic type declaration with
// the concrete arguments and renders the result.
func substitute(name string, tps []*TypeParam, args []ast.Expr, types map[string]ast.Expr) string {
	decl, ok := types[name]
	if !ok {
		return Render(nil)
	}
	st, ok := decl.(*ast.StructType)
	if !ok {
		return Render(decl)
	}
	var b strings.Builder
	b.WriteString("struct{")
	for i, f := range st.Fields.List {
		if i > 0 {
			b.WriteString("; ")
		}
		if len(f.Names) == 0 {
			b.WriteString("invalid type")
			continue
		}
		b.WriteString(f.Names[0].Name)
		b.WriteString(" ")
		b.WriteString(resolveTypeParam(f.Type, tps, args))
	}
	b.WriteString("}")
	return b.String()
}

func resolveTypeParam(e ast.Expr, tps []*TypeParam, args []ast.Expr) string {
	if id, ok := e.(*ast.Ident); ok {
		for i, tp := range tps {
			if tp.Name == id.Name {
				if i < len(args) {
					return Render(args[i])
				}
				return "string"
			}
		}
	}
	return Render(e)
}

// DefaultType returns the concrete type used to instantiate a type parameter.
func DefaultType(tp *TypeParam) string {
	c := strings.TrimSpace(tp.Constraint)
	if strings.Contains(c, "|") {
		return strings.TrimSpace(strings.SplitN(c, "|", 2)[0])
	}
	switch c {
	case "any":
		return "int"
	case "comparable":
		return "string"
	case "int":
		return "int"
	case "string":
		return "string"
	}
	if strings.HasPrefix(c, "~") {
		return strings.TrimSpace(c[1:])
	}
	return "string"
}

// IsBasicType reports whether the underlying type can be compared using ==.
func IsBasicType(e *Expression) bool {
	if e == nil {
		return false
	}
	return basicTypes[e.Underlying]
}

// Unquote strips the quotes of an import path.
func Unquote(s string) string {
	v, err := strconv.Unquote(s)
	if err != nil {
		return strings.Trim(s, "\"")
	}
	return v
}

// NameOf returns the implicit name of an import path.
func NameOf(path string) string {
	if i := strings.LastIndex(path, "/"); i >= 0 {
		path = path[i+1:]
	}
	if i := strings.LastIndex(path, "."); i >= 0 {
		path = path[i+1:]
	}
	return path
}

