}

// Field models a function parameter, result or struct field.
type Field struct {
	Name  string
	Type  *Expression
	Index int
}

// Receiver models the receiver of a method.
type Receiver struct {
	Field  *Field
	Fields []*Field
}

// TypeParam models a type parameter of a generic function or type.
type TypeParam struct {
	Name       string
	Constraint string
}

// Function models a function or method declaration.
type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
