cd /workspace && cat > internal/models/models.go <<'GOEOF'
// Package models holds the data structures used to describe the Go source
// that tests are generated for.
package models

import (
	"go/ast"
	"strconv"
	"strings"
)

// Expression models a Go type expression.
type Expression struct {
	Value      string
	IsStar     bool
	IsVariadic bool
	IsWriter   bool
	Underlying string
}

// Field models a function parameter, result or struct field.
type Field struct {
	Name  string
	Type  *Expression
	Index int
}

// Receiver models the receiver of a method.
type Receiver struct {
	Field  *Field
	Fields []*Field
}

// TypeParam models a type parameter of a generic function or type.
type TypeParam struct {
	Name       string
	Constraint string
}

// Function models a function or method declaration.
type Function struct {
	Name         string
	IsExported   bool
	Receiver     *Receiver
	Parameters   []*Field
	Results      []*Field
	ReturnsError bool
	TypeParams   []*TypeParam
	Body         string
}

// Import models an import declaration.
type Import struct {
	Name string
	Path string
}

// TypeDecl holds a type declaration found in the package.
type TypeDecl struct {
	Expr       ast.Expr
	TypeParams []*TypeParam
}

// Package models a Go package: the files that were parsed plus everything
// that is needed to render test files for it.
type Package struct {
	Name      string
	Files     []string
	Imports   []*Import
	Functions []*Function
	TestFuncs map[string]bool
	Types     map[string]*TypeDecl
}

// basicTypes is the set of Go types that can be compared using the == operator.
var basicTypes = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"uintptr": true, "float32": true, "float64": true,
	"complex64": true, "complex128": true, "string": true, "bool": true,
}

// predeclaredTypes are the type names that are always resolvable.
var predeclaredTypes = map[string]string{
	"bool": "bool", "byte": "byte", "complex64": "complex64", "complex128": "complex128",
	"error": "interface{Error() string}", "float32": "float32", "float64": "float64",
	"int": "int", "int8": "int8", "int16": "int16", "int32": "int32", "int64": "int64",
	"rune": "rune", "string": "string", "uint": "uint", "uint8": "uint8",
	"uint16": "uint16", "uint32": "uint32", "uint64": "uint64", "uintptr": "uintptr",
	"any": "any",
}

// writerType reports whether the expression is exactly io.Writer.
func writerType(e ast.Expr) bool {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	return id.Name == "io" && sel.Sel.Name == "Writer"
}

// Render renders a type expression back to Go source.  Composite types are
// rendered in a compact form that mirrors how gotests prints underlying types.
func Render(e ast.Expr) string {
	var b strings.Builder
	renderExpr(e, &b)
	return b.String()
}

func renderExpr(e ast.Expr, b *strings.Builder) {
	switch t := e.(type) {
	case nil:
		b.WriteString("invalid type")
	case *ast.Ident:
		b.WriteString(t.Name)
	case *ast.SelectorExpr:
		renderExpr(t.X, b)
		b.WriteString(".")
		b.WriteString(t.Sel.Name)
	case *ast.StarExpr:
		b.WriteString("*")
		renderExpr(t.X, b)
	case *ast.Ellipsis:
		b.WriteString("...")
		renderExpr(t.Elt, b)
	case *ast.ArrayType:
		b.WriteString("[")
		if t.Len != nil {
			b.WriteString(Render(t.Len))
		}
		b.WriteString("]")
		renderExpr(t.Elt, b)
	case *ast.MapType:
		b.WriteString("map[")
		renderExpr(t.Key, b)
		b.WriteString("]")
		renderExpr(t.Value, b)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			b.WriteString("chan<- ")
		case ast.RECV:
			b.WriteString("<-chan ")
		default:
			b.WriteString("chan ")
		}
		renderExpr(t.Value, b)
	case *ast.FuncType:
		b.WriteString("func(")
		renderFieldList(t.Params, b, true)
		b.WriteString(")")
		if t.Results != nil && len(t.Results.List) > 0 {
			b.WriteString(" ")
			if len(t.Results.List) == 1 && t.Results.List[0].Names == nil {
				renderExpr(t.Results.List[0].Type, b)
			} else {
				b.WriteString("(")
				renderFieldList(t.Results, b, true)
				b.WriteString(")")
			}
		}
	case *ast.StructType:
		b.WriteString("struct{")
		renderFieldList(t.Fields, b, false)
		b.WriteString("}")
	case *ast.InterfaceType:
		b.WriteString("interface{")
		renderMethodList(t.Methods, b)
		b.WriteString("}")
	case *ast.IndexExpr:
		renderExpr(t.X, b)
		b.WriteString("[")
		renderExpr(t.Index, b)
		b.WriteString("]")
	case *ast.IndexListExpr:
		renderExpr(t.X, b)
		b.WriteString("[")
		for i, idx := range t.Indices {
			if i > 0 {
				b.WriteString(", ")
			}
			renderExpr(idx, b)
		}
		b.WriteString("]")
	default:
		b.WriteString("invalid type")
	}
}

func renderFieldList(fl *ast.FieldList, b *strings.Builder, fn bool) {
	if fl == nil {
		return
	}
	for i, f := range fl.List {
		if i > 0 {
			b.WriteString("; ")
		}
		var tag string
		if f.Tag != nil {
			tag = f.Tag.Value
		}
		if len(f.Names) == 0 {
			if fn {
				renderExpr(f.Type, b)
			} else {
				b.WriteString("invalid type")
			}
			if tag != "" {
				b.WriteString(" " + tag)
			}
			continue
		}
		for j, n := range f.Names {
			if j > 0 {
				b.WriteString(", ")
			}
			b.WriteString(n.Name)
		}
		b.WriteString(" ")
		if ve, ok := f.Type.(*ast.Ellipsis); ok {
			b.WriteString("[]")
			renderExpr(ve.Elt, b)
		} else {
			renderExpr(f.Type, b)
		}
		if tag != "" {
			b.WriteString(" " + tag)
		}
	}
}

func renderMethodList(fl *ast.FieldList, b *strings.Builder) {
	if fl == nil {
		return
	}
	for i, f := range fl.List {
		if i > 0 {
			b.WriteString("; ")
		}
		if len(f.Names) == 0 {
			b.WriteString("invalid type")
			continue
		}
		b.WriteString(f.Names[0].Name)
		if ft, ok := f.Type.(*ast.FuncType); ok {
			b.WriteString("(")
			renderFieldList(ft.Params, b, true)
			b.WriteString(")")
			if ft.Results != nil && len(ft.Results.List) > 0 {
				b.WriteString(" ")
				if len(ft.Results.List) == 1 && ft.Results.List[0].Names == nil {
					renderExpr(ft.Results.List[0].Type, b)
				} else {
					b.WriteString("(")
					renderFieldList(ft.Results, b, true)
					b.WriteString(")")
				}
			}
			continue
		}
		renderExpr(f.Type, b)
	}
}

// modelable reports whether a type expression can be modelled, i.e. whether it
// only refers to types that are known inside the package.
func modelable(e ast.Expr) bool {
	switch t := e.(type) {
	case nil:
		return false
	case *ast.Ident:
		return true
	case *ast.StarExpr:
		return modelable(t.X)
	case *ast.Ellipsis:
		return modelable(t.Elt)
	case *ast.ArrayType:
		return (t.Len == nil || modelable(t.Len)) && modelable(t.Elt)
	case *ast.MapType:
		return modelable(t.Key) && modelable(t.Value)
	case *ast.ChanType:
		return modelable(t.Value)
	case *ast.FuncType:
		return modelableFields(t.Params) && modelableFields(t.Results)
	case *ast.StructType:
		return modelableFields(t.Fields)
	case *ast.InterfaceType:
		return modelableFields(t.Methods)
	case *ast.IndexExpr:
		return modelable(t.X) && modelable(t.Index)
	case *ast.IndexListExpr:
		ok := modelable(t.X)
		for _, i := range t.Indices {
			ok = ok && modelable(i)
		}
		return ok
	default:
		return false
	}
}

func modelableFields(fl *ast.FieldList) bool {
	if fl == nil {
		return true
	}
	for _, f := range fl.List {
		if !modelable(f.Type) {
			return false
		}
	}
	return true
}

// NewExpression builds the model of a type expression.
func NewExpression(e ast.Expr, isVariadic bool, types map[string]*TypeDecl) *Expression {
	res := &Expression{}
	if e == nil {
		res.Value = "invalid type"
		res.Underlying = "invalid type"
		return res
	}
	var value ast.Expr
	if st, ok := e.(*ast.StarExpr); ok && !isVariadic {
		res.IsStar = true
		value = st.X
	} else if ve, ok := e.(*ast.Ellipsis); ok && isVariadic {
		value = ve.Elt
	} else {
		value = e
	}
	res.Value = Render(value)
	res.Underlying = Underlying(e, types)
	if !isVariadic && writerType(e) {
		res.IsWriter = true
	}
	return res
}

// Underlying computes the underlying type of a type expression.
func Underlying(e ast.Expr, types map[string]*TypeDecl) string {
	if e == nil {
		return "invalid type"
	}
	if st, ok := e.(*ast.StarExpr); ok && !isVariadicExpr(e) {
		return underlyingTop(st.X, types)
	}
	if ve, ok := e.(*ast.Ellipsis); ok {
		return underlyingTop(ve.Elt, types)
	}
	return underlyingTop(e, types)
}

func isVariadicExpr(e ast.Expr) bool {
	_, ok := e.(*ast.Ellipsis)
	return ok
}

func underlyingTop(e ast.Expr, types map[string]*TypeDecl) string {
	if id, ok := e.(*ast.Ident); ok {
		if decl, ok := types[id.Name]; ok {
			if !modelable(decl.Expr) {
				return "invalid type"
			}
			if id2, isIdent := decl.Expr.(*ast.Ident); isIdent {
				return underlyingTop(id2, types)
			}
			if ix, ok := decl.Expr.(*ast.IndexExpr); ok {
				return instantiate(ix, types)
			}
			if ilx, ok := decl.Expr.(*ast.IndexListExpr); ok {
				return instantiateList(ilx, types)
			}
			return Render(decl.Expr)
		}
		if u, ok := predeclaredTypes[id.Name]; ok {
			return u
		}
		return ""
	}
	if !modelable(e) {
		return ""
	}
	if ix, ok := e.(*ast.IndexExpr); ok {
		return instantiate(ix, types)
	}
	if ilx, ok := e.(*ast.IndexListExpr); ok {
		return instantiateList(ilx, types)
	}
	return Render(e)
}

func instantiate(ix *ast.IndexExpr, types map[string]*TypeDecl) string {
	id, ok := ix.X.(*ast.Ident)
	if !ok {
		return Render(ix)
	}
	return substitute(id.Name, []ast.Expr{ix.Index}, types, Render(ix))
}

func instantiateList(ilx *ast.IndexListExpr, types map[string]*TypeDecl) string {
	id, ok := ilx.X.(*ast.Ident)
	if !ok {
		return Render(ilx)
	}
	return substitute(id.Name, ilx.Indices, types, Render(ilx))
}

func substitute(name string, args []ast.Expr, types map[string]*TypeDecl, fallback string) string {
	decl, ok := types[name]
	if !ok || len(decl.TypeParams) == 0 {
		return fallback
	}
	var b strings.Builder
	b.WriteString("struct{")
	st, ok := decl.Expr.(*ast.StructType)
	if !ok {
		return Render(decl.Expr)
	}
	for i, f := range st.Fields.List {
		if i > 0 {
			b.WriteString("; ")
		}
		if len(f.Names) == 0 {
			b.WriteString("invalid type")
			continue
		}
		b.WriteString(f.Names[0].Name)
		b.WriteString(" ")
		b.WriteString(resolveTypeParam(f.Type, decl.TypeParams, args))
	}
	b.WriteString("}")
	return b.String()
}

func resolveTypeParam(e ast.Expr, tps []*TypeParam, args []ast.Expr) string {
	if id, ok := e.(*ast.Ident); ok {
		for i, tp := range tps {
			if tp.Name == id.Name {
				if i < len(args) {
					return Render(args[i])
				}
				return "string"
			}
		}
	}
	return Render(e)
}

// DefaultType returns the concrete type used to instantiate a type parameter.
func DefaultType(tp *TypeParam) string {
	c := strings.TrimSpace(tp.Constraint)
	if strings.Contains(c, "|") {
		return strings.TrimSpace(strings.SplitN(c, "|", 2)[0])
	}
	switch c {
	case "any":
		return "int"
	case "comparable":
		return "string"
	case "int":
		return "int"
	case "string":
		return "string"
	}
	if strings.HasPrefix(c, "~") {
		return strings.TrimSpace(c[1:])
	}
	return "string"
}

// IsBasicType reports whether a type can be compared using the == operator.
func IsBasicType(e *Expression) bool {
	if e == nil {
		return false
	}
	return basicTypes[e.Underlying]
}

// Unquote strips the quotes of an import path.
func Unquote(s string) string {
	v, err := strconv.Unquote(s)
	if err != nil {
		return strings.Trim(s, "\"")
	}
	return v
}

// NameOf returns the implicit name of an import path.
func NameOf(path string) string {
	if i := strings.LastIndex(path, "/"); i >= 0 {
		path = path[i+1:]
	}
	if i := strings.LastIndex(path, "."); i >= 0 {
		path = path[i+1:]
	}
	return path
}
