// Package parser turns Go source files into the models used for rendering
// test files.
package parser

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/gotests/internal/models"
)

// Files expands the given paths into a list of Go source files.
func Files(paths []string) ([]string, error) {
	var result []string
	for _, path := range paths {
		if strings.HasSuffix(path, "/...") {
			dir := filepath.Dir(path)
			var files []string
			err := filepath.Walk(dir, func(p string, info os.FileInfo, err error) error {
				if err != nil {
					return err
				}
				if info.IsDir() {
					if p != dir && strings.HasPrefix(filepath.Base(p), ".") {
						return filepath.SkipDir
					}
					return nil
				}
				if !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
					return nil
				}
				files = append(files, p)
				return nil
			})
			if err != nil {
				return nil, fmt.Errorf("input.Files: filepath.Walk: %v\n", err)
			}
			sort.Strings(files)
			result = append(result, files...)
			continue
		}
		stat, err := os.Stat(path)
		if err != nil {
			return nil, fmt.Errorf("input.Files: os.Stat: %v\n", err)
		}
		if stat.IsDir() {
			entries, err := os.ReadDir(path)
			if err != nil {
				return nil, fmt.Errorf("input.Files: os.ReadDir: %v\n", err)
			}
			var files []string
			for _, e := range entries {
				if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
					continue
				}
				files = append(files, filepath.Join(path, e.Name()))
			}
			sort.Strings(files)
			result = append(result, files...)
			continue
		}
		if !strings.HasSuffix(path, ".go") {
			return nil, fmt.Errorf("input.Files: no Go source files found at %s", path)
		}
		result = append(result, path)
	}
	seen := map[string]bool{}
	var out []string
	for _, f := range result {
		if seen[f] {
			continue
		}
