			return nil, fmt.Errorf("Parser.Parse test file: target parser.ParseFile(): %v", err)
		}
		testFile = tf
		testFuncs = map[string]bool{}
		for _, d := range tf.Decls {
			if fd, ok := d.(*ast.FuncDecl); ok {
				testFuncs[fd.Name.Name] = true
			}
		}
		if testPath != path {
			f, err := parser.ParseFile(fset, testPath, nil, parser.ParseComments)
			if err != nil {
				return nil, fmt.Errorf("Parser.Parse test file: target parser.ParseFile(): %v", err)
			}
			collectImports(f, imports)
			collectTypes(f, types)
		}
	}

	pkg := &models.Package{
		Name:      target.Name.Name,
		Files:     append([]string{path}, others...),
		Imports:   imports,
		TestFuncs: testFuncs,
		Types:     types,
	}
	var body []byte
	if data, err := os.ReadFile(path); err == nil {
		body = data
	}
	for _, d := range target.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		fn := makeFunction(fd, body, fset, types)
		pkg.Functions = append(pkg.Functions, fn)
	}
	return pkg, nil
}

func testFileFor(path string) string {
	if strings.HasSuffix(path, "_test.go") {
		return path
	}
	return strings.TrimSuffix(path, ".go") + "_test.go"
}

func goFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: os.ReadDir: %v", err)
	}
	var files []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
			continue
		}
		files = append(files, filepath.Join(dir, e.Name()))
	}
	sort.Strings(files)
	return files, nil
}

func collectImports(f *ast.File, out []*models.Import) []*models.Import {
	for _, imp := range f.Imports {
		path := models.Unquote(imp.Path.Value)
		name := ""
		if imp.Name != nil {
			name = imp.Name.Name
		} else {
			name = models.NameOf(path)
		}
		out = append(out, &models.Import{Name: name, Path: path})
	}
	return out
}

func collectTypes(f *ast.File, types map[string]*models.TypeDecl) {
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			td := &models.TypeDecl{Expr: ts.Type}
			if ts.TypeParams != nil {
				td.TypeParams = makeTypeParams(ts.TypeParams)
			}
			types[ts.Name.Name] = td
		}
	}
}

func makeTypeParams(fl *ast.FieldList) []*models.TypeParam {
	var out []*models.TypeParam
	for _, f := range fl.List {
		var names []string
		for _, n := range f.Names {
			names = append(names, n.Name)
		}
		if len(names) == 0 {
			names = []string{models.Render(f.Type)}
		}
		for _, n := range names {
			out = append(out, &models.TypeParam{
				Name:       n,
				Constraint: constraintString(f.Type),
			})
		}
	}
	return out
}

func constraintString(e ast.Expr) string {
	switch t := e.(type) {
	case nil:
		return "any"
	case *ast.Ident:
		return t.Name
	}
	return models.Render(e)
}

func makeFunction(fd *ast.FuncDecl, src []byte, fset *token.FileSet, types map[string]*models.TypeDecl) *models.Function {
	fn := &models.Function{
		Name:       fd.Name.Name,
		IsExported: ast.IsExported(fd.Name.Name),
	}
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		r := &models.Receiver{}
		f := fd.Recv.List[0]
		var name string
		if len(f.Names) > 0 {
			name = f.Names[0].Name
		}
		isVariadic := false
		r.Field = &models.Field{
			Name:  name,
			Type:  models.NewExpression(f.Type, isVariadic, types),
			Index: 0,
		}
		r.Fields = structFields(f.Type, types)
		fn.Receiver = r
	}
	if fd.Type.Params != nil {
		for _, f := range fd.Type.Params.List {
			isVariadic := false
			if _, ok := f.Type.(*ast.Ellipsis); ok {
				isVariadic = true
			}
			var names []string
			for _, n := range f.Names {
				names = append(names, n.Name)
			}
			if len(names) == 0 {
				names = []string{""}
			}
			for _, n := range names {
				fn.Parameters = append(fn.Parameters, &models.Field{
					Name:  n,
					Type:  models.NewExpression(f.Type, isVariadic, types),
					Index: len(fn.Parameters),
				})
			}
		}
	}
	if fd.Type.Results != nil {
		for _, f := range fd.Type.Results.List {
			if id, ok := f.Type.(*ast.Ident); ok && id.Name == "error" {
				fn.ReturnsError = true
				continue
			}
			var names []string
			for _, n := range f.Names {
				names = append(names, n.Name)
			}
			if len(names) == 0 {
				names = []string{""}
			}
			for _, n := range names {
				fn.Results = append(fn.Results, &models.Field{
					Name:  n,
					Type:  models.NewExpression(f.Type, false, types),
					Index: len(fn.Results),
				})
			}
		}
	}
	if fd.Type.TypeParams != nil {
		fn.TypeParams = makeTypeParams(fd.Type.TypeParams)
	}
	if fd.Body != nil {
		start := fset.Position(fd.Body.Lbrace).Offset
		end := fset.Position(fd.Body.Rbrace).Offset
		if start >= 0 && end <= len(src) && start < end {
			fn.Body = string(src[start : end+1])
		}
	}
	return fn
}

func structFields(e ast.Expr, types map[string]*models.TypeDecl) []*models.Field {
	var base ast.Expr = e
	if st, ok := e.(*ast.StarExpr); ok {
		base = st.X
	}
	id, ok := base.(*ast.Ident)
	if !ok {
		return nil
	}
	decl, ok := types[id.Name]
	if !ok || len(decl.TypeParams) > 0 {
		return nil
	}
	st, ok := decl.Expr.(*ast.StructType)
	if !ok {
		return nil
	}
	var out []*models.Field
	for _, f := range st.Fields.List {
		if len(f.Names) == 0 {
			continue
		}
		for _, n := range f.Names {
			out = append(out, &models.Field{
				Name:  n.Name,
				Type:  models.NewExpression(f.Type, false, types),
				Index: len(out),
			})
		}
	}
	return out
}
