// Package render turns function models into Go test functions.
package render

import (
	"strings"
	"text/template"
	"unicode"
	"unicode/utf8"

	"github.com/cweill/gotests/internal/models"
)

var defaultTemplateString = `func Test{{.TestName}}(t *testing.T) {
{{- if .Parallel}}
	t.Parallel()
{{- end}}
{{- .FieldsBlock}}
{{- .ArgsBlock}}
	tests := {{if .Named}}map[string]struct {{{else}}[]struct {{{end}}
		name string
{{- .ReceiverStructField}}
{{- if .NeedsConstructor}}
		fields fields
{{- end}}
{{- if .Args}}
		args args
{{- end}}
{{- range .TestResults}}
		{{$.ResultField .}}
{{- end}}
{{- range .Writers}}
		{{$.WriterField .}}
{{- end}}
{{- if .ReturnsError}}
		wantErr bool
{{- end}}
	}{
{{- .TestCases}}
	}
	for {{if .Named}}name, tt{{else}}_, tt{{end}} := range tests {
{{- if .Subtests}}
		t.Run({{if .Named}}name{{else}}tt.name{{end}}, func(t *testing.T) {
{{- if .Parallel}}
			t.Parallel()
{{- end}}
{{- end}}
{{- .Body}}
{{- if .Subtests}}
		})
{{- end}}
	}
}
`

// TestOptions holds the options that influence how a test function is
// rendered.
type TestOptions struct {
	PrintInputs     bool
	Subtests        bool
	Parallel        bool
	Named           bool
	UseGoCmp        bool
	TemplateParams  map[string]interface{}
	AIGeneratedCases []interface{}
}

// capitalize upper-cases the first letter of a string.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

var _ = strings.ToLower
GOEOF
echo ok

