// promptText builds the prompt sent to the AI provider.
func (c *Client) promptText(fn *models.Function, scaffold, previousErr, previousResponse string) string {
	var b strings.Builder
	b.WriteString("You are a Go testing expert. Generate test cases for the following function.\n\n")
	b.WriteString("Function to test:\n```go\n")
	b.WriteString(fn.Source())
	b.WriteString("\n```\n\n")
	b.WriteString("Here is the test scaffold:\n```go\n")
	b.WriteString(scaffold)
	b.WriteString("\n```\n\n")
	fmt.Fprintf(&b, "Generate between %d and %d test cases. Each test case must have UNIQUE, DIFFERENT input values.\n", c.cfg.MinCases, c.cfg.MaxCases)
	if fn.ReturnsError {
		b.WriteString("Include: 1 valid case, 1 edge case, 1 error case.\n\n")
	} else {
		b.WriteString("Include: valid inputs, edge cases (zero/empty/nil), boundary values.\n\n")
	}
	b.WriteString("Example format:\n```go\n")
	b.WriteString(fn.Example())
	b.WriteString("\n```\n\n")
	b.WriteString("Requirements:\n")
	b.WriteString("- DIFFERENT values in each test case (NO duplicates)\n")
	b.WriteString("- Use NAMED fields (e.g., field: value)\n")
	b.WriteString("- Use exact field names from scaffold\n")
	b.WriteString("- Use natural language test names with spaces (e.g., \"valid input\", not \"valid_input\")\n")
	b.WriteString("- Valid Go syntax, realistic values\n")
	if fn.ReturnsError {
		b.WriteString("- Set wantErr based on expected error\n")
	}
	b.WriteString("\nOutput ONLY the test case array, no explanations:\n")
	if previousErr != "" {
		fmt.Fprintf(&b, "PREVIOUS ATTEMPT FAILED:\n%v\n\nLLM Response:\n%s\n\nPlease fix the above issue.\n\n", previousErr, previousResponse)
	}
	b.WriteString("Now fill in the scaffold above by replacing '// TODO: Add test cases.' with your test cases:\n```go\n")
	b.WriteString(scaffold)
	b.WriteString("\n```\n")
	return b.String()
}

// generate sends the prompt and returns the raw response text.
func (c *Client) generate(fn *models.Function, scaffold string) (string, error) {
	const attempts = 3
	var lastErr error
	var lastResponse string
	prompt := c.promptText(fn, scaffold, "", "")
	for i := 0; i < attempts; i++ {
		if i > 0 {
			prompt = c.promptText(fn, scaffold, lastErr.Error(), lastResponse)
		}
		req := generateRequest{
			Model:   c.cfg.Model,
			Options: map[string]interface{}{"seed": 42, "temperature": 0},
			Prompt:  prompt,
			Stream:  false,
		}
		data, err := json.Marshal(req)
		if err != nil {
			return "", err
		}
		resp, err := httpPost(c.cfg.Endpoint+"/api/generate", data)
		if err != nil {
			lastErr = err
			lastResponse = ""
			continue
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			lastErr = fmt.Errorf("AI provider returned status %d", resp.StatusCode)
			lastResponse = ""
			continue
		}
		var gr generateResponse
		if err := json.NewDecoder(resp.Body).Decode(&gr); err != nil {
			lastErr = err
			lastResponse = ""
			continue
		}
		lastResponse = gr.Response
		cases, perr := ParseCases(gr.Response)
		if perr != nil {
			lastErr = perr
			continue
		}
		if err := Validate(cases, fn); err != nil {
			lastErr = err
			continue
		}
		return lastResponse, nil
	}
	return "", fmt.Errorf("failed after %d attempts: %v\n\nLLM Response:\n%s", attempts, lastErr, lastResponse)
}
GOEOF
echo ok"}

