// TypeValue returns the type text of a field with the type parameters replaced
// by their default concrete types.
func (f *Function) TypeValue(e *Expression) string {
	return f.instantiate(e.Value)
}

// ArgValue returns the type used for a parameter in the args struct.
func (f *Function) ArgValue(e *Expression) string {
	v := f.instantiate(e.Value)
	if e.IsVariadic {
		return "[]" + v
	}
	return v
}

// RawType returns the type text of a field without instantiating type
// parameters.
func (f *Function) RawType(e *Expression) string {
	return e.Value
}

func (f *Function) instantiate(s string) string {
	for _, tp := range f.TypeParams {
		s = strings.ReplaceAll(s, tp.Name, DefaultType(tp))
	}
	return s
}

// Args returns the parameters that end up in the args struct.
func (f *Function) Args() []*Field {
	var out []*Field
	for _, p := range f.Parameters {
		if p.Type.IsWriter {
			continue
		}
		out = append(out, p)
	}
	return out
}

// Writers returns the io.Writer parameters.
func (f *Function) Writers() []*Field {
	var out []*Field
	for _, p := range f.Parameters {
		if p.Type.IsWriter {
			out = append(out, p)
		}
	}
	return out
}

// ReceiverVar returns the variable name used for the receiver.
func (f *Function) ReceiverVar() string {
	if f.Receiver == nil {
		return ""
	}
	name := f.Receiver.Field.Name
	if name == "" {
		name = strings.ToLower(firstRune(f.Receiver.Field.Type.Value) + "")
	}
	if name == "t" {
		return "tr"
	}
	return name
}

// ReceiverType returns the type text of the receiver, instantiated.
func (f *Function) ReceiverType() string {
	if f.Receiver == nil {
		return ""
	}
	t := f.instantiate(f.Receiver.Field.Type.Value)
	if f.Receiver.Field.Type.IsStar {
		return "*" + t
	}
	return t
}

// RawReceiverType returns the receiver type text without instantiating.
func (f *Function) RawReceiverType() string {
	if f.Receiver == nil {
		return ""
	}
	t := f.Receiver.Field.Type.Value
	if f.Receiver.Field.Type.IsStar {
		return "*" + t
	}
	return t
}

// NeedsConstructor reports whether a constructor must be emitted for the
// receiver.
func (f *Function) NeedsConstructor() bool {
	if f.Receiver == nil {
		return false
