// renderU renders a type expression for use as an underlying type.  Types that
// cannot be resolved are reported as "invalid type".
func renderU(e ast.Expr) string {
	var b strings.Builder
	renderUExpr(e, &b)
	return b.String()
}

func renderUExpr(e ast.Expr, b *strings.Builder) {
	switch t := e.(type) {
	case nil:
		b.WriteString("invalid type")
	case *ast.Ident:
		b.WriteString(t.Name)
	case *ast.SelectorExpr:
		b.WriteString("invalid type")
	case *ast.ParenExpr:
		renderUExpr(t.X, b)
	case *ast.StarExpr:
		b.WriteString("*")
		renderUExpr(t.X, b)
	case *ast.Ellipsis:
		b.WriteString("[]")
		renderUExpr(t.Elt, b)
	case *ast.ArrayType:
		b.WriteString("[")
		if t.Len != nil {
			b.WriteString(renderUExprStr(t.Len))
		}
		b.WriteString("]")
		renderUExpr(t.Elt, b)
	case *ast.MapType:
		b.WriteString("map[")
		renderUExpr(t.Key, b)
		b.WriteString("]")
		renderUExpr(t.Value, b)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			b.WriteString("chan<- ")
		case ast.RECV:
			b.WriteString("<-chan ")
		default:
			b.WriteString("chan ")
		}
		renderUExpr(t.Value, b)
	case *ast.FuncType:
		b.WriteString("func(")
		renderUFields(t.Params, b, true)
		b.WriteString(")")
		if t.Results != nil && len(t.Results.List) > 0 {
			b.WriteString(" ")
			if len(t.Results.List) == 1 && t.Results.List[0].Names == nil {
				renderUExpr(t.Results.List[0].Type, b)
			} else {
				b.WriteString("(")
				renderUFields(t.Results, b, true)
				b.WriteString(")")
			}
		}
	case *ast.StructType:
		b.WriteString("struct{")
		renderUFields(t.Fields, b, false)
		b.WriteString("}")
	case *ast.InterfaceType:
		b.WriteString("interface{")
		renderUFields(t.Methods, b, false)
		b.WriteString("}")
	case *ast.IndexExpr:
		b.WriteString(renderUExprStr(t.X))
		b.WriteString("[")
		renderUExpr(t.Index, b)
		b.WriteString("]")
	case *ast.IndexListExpr:
		b.WriteString(renderUExprStr(t.X))
		b.WriteString("[")
		for i, idx := range t.Indices {
			if i > 0 {
				b.WriteString(", ")
			}
			renderUExpr(idx, b)
		}
		b.WriteString("]")
	default:
		b.WriteString("invalid type")
	}
}

func renderUExprStr(e ast.Expr) string {
	var b strings.Builder
	renderUExpr(e, &b)
	return b.String()
}

func renderUFields(fl *ast.FieldList, b *strings.Builder, fn bool) {
	if fl == nil {
		return
	}
	for i, f := range fl.List {
		if i > 0 {
			b.WriteString("; ")
		}
		var tag string
		if f.Tag != nil {
			tag = f.Tag.Value
		}
		if len(f.Names) == 0 {
			if fn {
				renderUExpr(f.Type, b)
			} else {
				b.WriteString("invalid type")
			}
			if tag != "" {
				b.WriteString(" " + tag)
			}
			continue
		}
		for j, n := range f.Names {
			if j > 0 {
				b.WriteString(", ")
			}
			b.WriteString(n.Name)
		}
		b.WriteString(" ")
		if ve, ok := f.Type.(*ast.Ellipsis); ok {
			b.WriteString("[]")
			renderUExpr(ve.Elt, b)
		} else {
			renderUExpr(f.Type, b)
		}
		if tag != "" {
			b.WriteString(" " + tag)
		}
	}
}
