	UseGoCmp         bool
	TemplateParams   map[string]interface{}
	AIGeneratedCases []interface{}
}

// TestFunction renders a single test function for fn.
func TestFunction(fn *models.Function, opt *Options, cases []*ai.TestCase, params map[string]interface{}) (string, error) {
	if opt.Template != nil {
		t := opt.Template.Lookup("function")
		if t != nil {
			var b strings.Builder
			d := &data{
				Function:         fn,
				PrintInputs:      opt.PrintInputs,
				Subtests:         opt.Subtests,
				Parallel:         opt.Parallel,
				Named:            opt.Named,
				UseGoCmp:         opt.UseGoCmp,
				TemplateParams:   params,
				AIGeneratedCases: aiCases(cases),
			}
			if err := t.Execute(&b, d); err != nil {
				return "", fmt.Errorf("render.TestFunction: %v", err)
			}
			return b.String(), nil
		}
	}
	var b strings.Builder
	writeTestFunction(&b, fn, opt, cases)
	return b.String(), nil
}

func aiCases(cases []*ai.TestCase) []interface{} {
	var out []interface{}
	for _, c := range cases {
		out = append(out, c)
	}
	return out
}

func writeTestFunction(b *strings.Builder, fn *models.Function, opt *Options, cases []*ai.TestCase) {
	fmt.Fprintf(b, "func Test%s(t *testing.T) {\n", fn.TestName())
	if opt.Parallel {
		b.WriteString("\tt.Parallel()\n")
	}
	if fields := fn.ReceiverFields(); len(fields) > 0 {
		b.WriteString("\ttype fields struct {\n")
		for _, f := range fields {
			fmt.Fprintf(b, "\t\t%s %s\n", f.Name, fn.ArgValue(f.Type))
		}
		b.WriteString("\t}\n")
	}
	args := fn.Args()
	if len(args) > 0 {
		b.WriteString("\ttype args struct {\n")
		for _, a := range args {
			fmt.Fprintf(b, "\t\t%s %s\n", a.Name, fn.ArgValue(a.Type))
		}
		b.WriteString("\t}\n")
	}
	if opt.Named {
		b.WriteString("\ttests := map[string]struct {\n")
	} else {
		b.WriteString("\ttests := []struct {\n")
	}
	if !opt.Named {
		b.WriteString("\t\tname string\n")
	}
	if fn.Receiver != nil && fn.ReceiverStructField() {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.ReceiverVar(), fn.ReceiverType())
	}
	if fn.NeedsConstructor() {
		b.WriteString("\t\tfields fields\n")
	}
	if len(args) > 0 {
		b.WriteString("\t\targs args\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.WantName(i), fn.ArgValue(fn.Results[i].Type))
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "\t\twant%s string\n", capitalize(w.Name))
	}
	if fn.ReturnsError {
		b.WriteString("\t\twantErr bool\n")
	}
	b.WriteString("\t}{\n")
	if len(cases) > 0 {
		b.WriteString(strings.Join(ai.CasesBlock(fn, cases), ""))
	} else {
		b.WriteString("\t\t// TODO: Add test cases.\n")
	}
	b.WriteString("\t}\n")
	if opt.Named {
		b.WriteString("\tfor name, tt := range tests {\n")
	} else {
		b.WriteString("\tfor _, tt := range tests {\n")
	}
	if opt.Subtests {
		if opt.Named {
			b.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			b.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opt.Parallel {
			b.WriteString("\t\t\tt.Parallel()\n")
		}
	}
	writeTestBody(b, fn, opt)
	if opt.Subtests {
		b.WriteString("\t\t})\n")
	}
	b.WriteString("\t}\n}\n")
}

func writeTestBody(b *strings.Builder, fn *models.Function, opt *Options) {
	indent := "\t\t"
	if opt.Subtests {
		indent = "\t\t\t"
	}
	if fn.NeedsConstructor() {
		typ := fn.ReceiverType()
		if fn.Receiver.Field.Type.IsStar {
			typ = "&" + typ
		}
		fields := fn.ReceiverFields()
		if len(fields) == 0 {
			fmt.Fprintf(b, "%s%s := %s{}\n", indent, fn.ReceiverVar(), typ)
		} else {
			fmt.Fprintf(b, "%s%s := %s{\n", indent, fn.ReceiverVar(), typ)
			for _, f := range fields {
				fmt.Fprintf(b, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
			}
			fmt.Fprintf(b, "%s}\n", indent)
		}
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "%s%s := &bytes.Buffer{}\n", indent, w.Name)
	}
	callArgs := callArgs(fn)
	call := fn.CallTarget() + fn.TypeArgs()
	results := fn.Results
	switch {
	case len(results) == 1 && !fn.ReturnsError:
		r := results[0]
		var got string
		if len(results) == 1 && results[0].Name != "" {
			got = "got" + capitalize(results[0].Name)
		} else {
			got = "got"
		}
		writeResultCheck(b, fn, opt, indent, call, callArgs, got, r, 0, singleMsg(fn), true)
	case fn.ReturnsError && len(results) == 0:
		fmt.Fprintf(b, "%sif err := %s(%s); (err != nil) != tt.wantErr {\n", indent, call, callArgs)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, err, tt.wantErr)\n", indent, errMsg(fn, "", opt, true))
		b.WriteString(indent + "}\n")
	case len(results) == 0 && len(fn.Writers()) == 0:
		fmt.Fprintf(b, "%s%s(%s)\n", indent, call, callArgs)
	default:
		var gotVars []string
		for i := range results {
			gotVars = append(gotVars, gotVar(results[i], i))
		}
		if fn.ReturnsError {
			gotVars = append(gotVars, "err")
		}
		fmt.Fprintf(b, "%s%s := %s(%s)\n", indent, strings.Join(gotVars, ", "), call, callArgs)
		if fn.ReturnsError {
			if opt.Subtests {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				fmt.Fprintf(b, "%s\tt.Fatalf(%q, err, tt.wantErr)\n", indent, errMsg(fn, "", opt, true))
				b.WriteString(indent + "}\n")
				b.WriteString(indent + "if tt.wantErr {\n")
				b.WriteString(indent + "\treturn\n")
				b.WriteString(indent + "}\n")
			} else {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				fmt.Fprintf(b, "%s\tt.Errorf(%q, tt.name, err, tt.wantErr)\n", indent, errMsg(fn, "%q. ", opt, true))
				b.WriteString(indent + "\tcontinue\n")
				b.WriteString(indent + "}\n")
				b.WriteString(indent + "if tt.wantErr {\n")
				b.WriteString(indent + "\treturn\n")
				b.WriteString(indent + "}\n")
			}
		}
		for i := range results {
			r := results[i]
			got := gotVar(r, i)
			writeResultCheck(b, fn, opt, indent, "", "", got, r, i, multiMsg(fn, got), false)
		}
	}
	for _, w := range fn.Writers() {
		got := "got" + capitalize(w.Name)
		want := "want" + capitalize(w.Name)
		fmt.Fprintf(b, "%sif %s := %s.String(); %s != tt.%s {\n", indent, got, w.Name, got, want)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, errMsg(fn, "", opt, false), got, want)
		b.WriteString(indent + "}\n")
	}
}

func gotVar(r *models.Field, i int) string {
	if r.Name != "" {
		return "got" + capitalize(r.Name)
	}
	if i == 0 {
		return "got"
	}
	return fmt.Sprintf("got%d", i)
}

func singleMsg(fn *models.Function) string { return "" }

func multiMsg(fn *models.Function, got string) string { return "" }

// writeResultCheck writes the comparison block for a single result.
func writeResultCheck(b *strings.Builder, fn *models.Function, opt *Options, indent, call, callArgs, got string, r *models.Field, index int, msg string, inline bool) {
	want := fn.WantName(index)
	testable := models.IsBasicType(r.Type)
	if testable {
		if inline {
			fmt.Fprintf(b, "%sif %s := %s(%s); %s != tt.%s {\n", indent, got, call, callArgs, got, want)
		} else {
			fmt.Fprintf(b, "%sif %s != tt.%s {\n", indent, got, want)
		}
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, errMsg(fn, "", opt, false), got, want)
		b.WriteString(indent + "}\n")
		return
	}
	if opt.UseGoCmp {
		if inline {
			fmt.Fprintf(b, "%sif %s := %s(%s); !cmp.Equal(tt.%s, %s) {\n", indent, got, call, callArgs, want, got)
		} else {
			fmt.Fprintf(b, "%sif !cmp.Equal(tt.%s, %s) {\n", indent, want, got)
		}
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", indent, errMsg(fn, "", opt, false), got, want, want, got)
		b.WriteString(indent + "}\n")
		return
	}
	if inline {
		fmt.Fprintf(b, "%sif %s := %s(%s); !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, call, callArgs, got, want)
	} else {
		fmt.Fprintf(b, "%sif !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, want)
	}
	fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, errMsg(fn, "", opt, false), got, want)
	b.WriteString(indent + "}\n")
}
GOEOF
echo ok"}

