            }
        }
        if args := fn.Args(); len(args) > 0 {
            out = append(out, "\t\t\targs: args{\n")
            for _, a := range args {
                out = append(out, "\t\t\t\t" + a.Name + ": " + c.render(c.Args[a.Name]) + ",\n")
            }
            out = append(out, "\t\t\t},\n")
        }
        for i := range fn.Results {
