{"command": "cd /workspace && cat >> internal/ai/ai.go <<'GOEOF'

// parseError is returned when the AI response cannot be parsed.
const wrapperPrefix = "package test\n\nfunc _() {\n\ttests := []struct {\n"
const wrapperSuffix = "\t}\n}\n"

// scaffoldFields renders the fields of the test scaffold.
func scaffoldFields(fn *models.Function, indent string) string {
	var b strings.Builder
	b.WriteString(indent + "name string\n")
	if fn.Receiver != nil {
		b.WriteString(indent + "c " + fn.RawReceiverType() + "\n")
	}
	if len(fn.Args()) > 0 {
		b.WriteString(indent + "args args\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(b, "%swant%d %s\n", indent, i, fn.RawType(fn.Results[i].Type))
	}
	for i, w := range fn.Writers() {
		fmt.Fprintf(b, "%swant%d string\n", indent, len(fn.Results)+i)
	}
	if fn.ReturnsError {
		b.WriteString(indent + "wantErr bool\n")
	}
	return b.String()
}

// Scaffold renders the test scaffold sent to the AI provider.
func Scaffold(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("tests := []struct {\n")
	b.WriteString(scaffoldFields(fn, "\t"))
	b.WriteString("} {\n")
	b.WriteString("\t// TODO: Add test cases.\n")
	b.WriteString("}")
	return b.String()
}

// Example renders the example test case sent to the AI provider.
func Example(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("{\n")
	b.WriteString("    name: \"descriptive test name\",\n")
	if fn.Receiver != nil {
		fmt.Fprintf(&b, "    c: &%s{},\n", fn.RawReceiverType())
	}
	if args := fn.Args(); len(args) > 0 {
		var parts []string
		for _, a := range args {
			parts = append(parts, a.Name+": <value>")
		}
		b.WriteString("    args: args{" + strings.Join(parts, ", ") + "},\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(&b, "    want%d: <expected_value>,\n", i)
	}
	for i := range fn.Writers() {
		fmt.Fprintf(&b, "    want%d: <expected_value>,\n", len(fn.Results)+i)
	}
	if fn.ReturnsError {
		b.WriteString("    wantErr: false,\n")
	}
	b.WriteString("},")
	return b.String()
}

// ParseCases extracts the test cases from an AI response.
func ParseCases(response string) ([]*TestCase, error) {
	fields := scaffoldStructFields(response)
	src := wrapperPrefix + fields + "\t}{\n" + response + wrapperSuffix
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "test.go", src, 0)
	if err != nil {
		return nil, fmt.Errorf("parse Go test cases: parse Go code: %v", err)
	}
	var cases []*TestCase
	lit := findCompositeLit(f)
	if lit != nil {
		for _, e := range lit.Elts {
			cl, ok := e.(*ast.CompositeLit)
			if !ok {
