// Package render turns function models into Go test functions.
package render

import (
	"fmt"
	"strings"
	"text/template"
	"unicode"
	"unicode/utf8"

	"github.com/cweill/gotests/internal/ai"
	"github.com/cweill/gotests/internal/models"
)

// Options holds the options that influence how a test function is rendered.
type Options struct {
	PrintInputs bool
	Subtests    bool
	Parallel    bool
	Named       bool
	UseGoCmp    bool
	Template    *template.Template
}

// capitalize upper-cases the first letter of a string.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

// data is the structure passed to custom test templates.
type data struct {
	*models.Function
	PrintInputs      bool
	Subtests         bool
	Parallel         bool
	Named            bool
	UseGoCmp         bool
	TemplateParams   map[string]interface{}
	AIGeneratedCases []interface{}
}

// TestFunction renders a single test function for fn.
func TestFunction(fn *models.Function, opt *Options, cases []*ai.TestCase, params map[string]interface{}) (string, error) {
	if opt.Template != nil {
		if t := opt.Template.Lookup("function"); t != nil {
			var b strings.Builder
			d := &data{
				Function:         fn,
				PrintInputs:      opt.PrintInputs,
				Subtests:         opt.Subtests,
				Parallel:         opt.Parallel,
				Named:            opt.Named,
				UseGoCmp:         opt.UseGoCmp,
				TemplateParams:   params,
				AIGeneratedCases: aiCases(cases),
			}
			if err := t.Execute(&b, d); err != nil {
				return "", fmt.Errorf("render.TestFunction: %v", err)
			}
			return b.String(), nil
		}
	}
	var b strings.Builder
	writeTestFunction(&b, fn, opt, cases)
	return b.String(), nil
}

func aiCases(cases []*ai.TestCase) []interface{} {
	var out []interface{}
	for _, c := range cases {
		out = append(out, c)
	}
	return out
}

func writeTestFunction(b *strings.Builder, fn *models.Function, opt *Options, cases []*ai.TestCase) {
	fmt.Fprintf(b, "func Test%s(t *testing.T) {\n", fn.TestName())
	if opt.Parallel {
		b.WriteString("\tt.Parallel()\n")
	}
	if fields := fn.ReceiverFields(); len(fields) > 0 {
		b.WriteString("\ttype fields struct {\n")
		for _, f := range fields {
			fmt.Fprintf(b, "\t\t%s %s\n", f.Name, fn.ArgValue(f.Type))
		}
		b.WriteString("\t}\n")
	}
	args := fn.Args()
	if len(args) > 0 {
		b.WriteString("\ttype args struct {\n")
		for _, a := range args {
			fmt.Fprintf(b, "\t\t%s %s\n", a.Name, fn.ArgValue(a.Type))
		}
		b.WriteString("\t}\n")
	}
	if opt.Named {
		b.WriteString("\ttests := map[string]struct {\n")
	} else {
		b.WriteString("\ttests := []struct {\n")
	}
	if !opt.Named {
		b.WriteString("\t\tname string\n")
	}
	if fn.Receiver != nil && fn.ReceiverStructField() {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.ReceiverVar(), fn.ReceiverType())
	}
	if fn.NeedsConstructor() {
		b.WriteString("\t\tfields fields\n")
	}
	if len(args) > 0 {
		b.WriteString("\t\targs args\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.WantName(i), fn.ArgValue(fn.Results[i].Type))
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "\t\twant%s string\n", capitalize(w.Name))
	}
	if fn.ReturnsError {
		b.WriteString("\t\twantErr bool\n")
	}
	b.WriteString("\t}{\n")
	if len(cases) > 0 {
		for _, l := range ai.CasesBlock(fn, cases) {
			b.WriteString(l)
		}
	} else {
		b.WriteString("\t\t// TODO: Add test cases.\n")
	}
	b.WriteString("\t}\n")
	if opt.Named {
		b.WriteString("\tfor name, tt := range tests {\n")
	} else {
		b.WriteString("\tfor _, tt := range tests {\n")
	}
	if opt.Subtests {
		if opt.Named {
			b.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			b.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opt.Parallel {
			b.WriteString("\t\t\tt.Parallel()\n")
		}
	}
	writeTestBody(b, fn, opt)
	if opt.Subtests {
		b.WriteString("\t\t})\n")
	}
	b.WriteString("\t}\n}\n")
}

// inputs returns the format specifier and argument expressions used for the
// function inputs in error messages.
func inputs(fn *models.Function, opt *Options) (string, []string) {
	if !opt.PrintInputs || len(fn.Parameters) == 0 {
		return "", nil
	}
	var parts []string
	var args []string
	for _, p := range fn.Parameters {
		parts = append(parts, "%v")
		args = append(args, "tt.args."+p.Name)
	}
	return "(" + strings.Join(parts, ", ") + ")", args
}

func msgPrefix(opt *Options) string {
	if opt.Subtests {
		return ""
	}
	return "%q. "
}

func writeTestBody(b *strings.Builder, fn *models.Function, opt *Options) {
	indent := "\t\t"
	if opt.Subtests {
		indent = "\t\t\t"
	}
	if fn.NeedsConstructor() {
		typ := fn.ReceiverType()
		if fn.Receiver.Field.Type.IsStar {
			typ = "&" + typ
		}
		fields := fn.ReceiverFields()
		if len(fields) == 0 {
			fmt.Fprintf(b, "%s%s := %s{}\n", indent, fn.ReceiverVar(), typ)
		} else {
			fmt.Fprintf(b, "%s%s := %s{\n", indent, fn.ReceiverVar(), typ)
			for _, f := range fields {
				fmt.Fprintf(b, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
			}
			fmt.Fprintf(b, "%s}\n", indent)
		}
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "%s%s := &bytes.Buffer{}\n", indent, w.Name)
	}
	callArgs := callArgs(fn)
	call := fn.CallTarget() + fn.TypeArgs()
	results := fn.Results
	inFmt, inArgs := inputs(fn, opt)
	switch {
	case len(results) == 1 && !fn.ReturnsError:
		writeSingleResult(b, fn, opt, indent, call, callArgs, inFmt, inArgs)
	case fn.ReturnsError && len(results) == 0:
		fmt.Fprintf(b, "%sif err := %s(%s); (err != nil) != tt.wantErr {\n", indent, call, callArgs)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, err, tt.wantErr)\n", indent, msg(fn, opt, true, false, inFmt))
		b.WriteString(indent + "}\n")
	case len(results) == 0 && len(fn.Writers()) == 0:
		fmt.Fprintf(b, "%s%s(%s)\n", indent, call, callArgs)
	default:
		var gotVars []string
		for i := range results {
			gotVars = append(gotVars, gotVar(results[i], i))
		}
		if fn.ReturnsError {
			gotVars = append(gotVars, "err")
		}
		fmt.Fprintf(b, "%s%s := %s(%s)\n", indent, strings.Join(gotVars, ", "), call, callArgs)
		if fn.ReturnsError {
			if opt.Subtests {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				fmt.Fprintf(b, "%s\tt.Fatalf(%q, err, tt.wantErr)\n", indent, msg(fn, opt, true, false, inFmt))
				b.WriteString(indent + "}\n")
			} else {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				fmt.Fprintf(b, "%s\tt.Errorf(%q, tt.name, err, tt.wantErr)\n", indent, msg(fn, opt, true, false, "%q. "+inFmt))
				b.WriteString(indent + "\tcontinue\n")
				b.WriteString(indent + "}\n")
			}
			b.WriteString(indent + "if tt.wantErr {\n")
			b.WriteString(indent + "\treturn\n")
			b.WriteString(indent + "}\n")
		}
		for i := range results {
			writeResultCheck(b, fn, opt, indent, gotVar(results[i], i), i, inFmt, inArgs, false)
		}
	}
	for _, w := range fn.Writers() {
		got := "got" + capitalize(w.Name)
		want := "want" + capitalize(w.Name)
		fmt.Fprintf(b, "%sif %s := %s.String(); %s != tt.%s {\n", indent, got, w.Name, got, want)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, msg(fn, opt, false, false, inFmt), got, want)
		b.WriteString(indent + "}\n")
	}
}

func gotVar(r *models.Field, i int) string {
	if r.Name != "" {
		return "got" + capitalize(r.Name)
	}
	if i == 0 {
		return "got"
	}
	return fmt.Sprintf("got%d", i)
}

// writeSingleResult writes the body for a function with a single result and no
// error result.
func writeSingleResult(b *strings.Builder, fn *models.Function, opt *Options, indent, call, callArgs, inFmt string, inArgs []string) {
	r := fn.Results[0]
	got := gotVar(r, 0)
	want := fn.WantName(0)
	if models.IsBasicType(r.Type) {
		fmt.Fprintf(b, "%sif %s := %s(%s); %s != tt.%s {\n", indent, got, call, callArgs, got, want)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, msg(fn, opt, false, false, inFmt), got, want)
		b.WriteString(indent + "}\n")
		return
	}
	if opt.UseGoCmp {
		fmt.Fprintf(b, "%sif %s := %s(%s); !cmp.Equal(tt.%s, %s) {\n", indent, got, call, callArgs, want, got)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", indent, msg(fn, opt, false, true, inFmt), got, want, want, got)
		b.WriteString(indent + "}\n")
		return
	}
	fmt.Fprintf(b, "%sif %s := %s(%s); !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, call, callArgs, got, want)
	fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, msg(fn, opt, false, false, inFmt), got, want)
	b.WriteString(indent + "}\n")
}

// writeResultCheck writes the comparison block for one of several results.
func writeResultCheck(b *strings.Builder, fn *models.Function, opt *Options, indent, got string, index int, inFmt string, inArgs []string, inline bool) {
	r := fn.Results[index]
	want := fn.WantName(index)
	multi := len(fn.Results) > 1
	if models.IsBasicType(r.Type) {
		fmt.Fprintf(b, "%sif %s != tt.%s {\n", indent, got, want)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, msg(fn, opt, false, false, inFmt, multi, got), got, want)
		b.WriteString(indent + "}\n")
		return
	}
	if opt.UseGoCmp {
		fmt.Fprintf(b, "%sif !cmp.Equal(tt.%s, %s) {\n", indent, want, got)
		fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", indent, msg(fn, opt, false, true, inFmt, multi, got), got, want, want, got)
		b.WriteString(indent + "}\n")
		return
	}
	fmt.Fprintf(b, "%sif !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, want)
	fmt.Fprintf(b, "%s\tt.Errorf(%q, %s, tt.%s)\n", indent, msg(fn, opt, false, false, inFmt, multi, got), got, want)
	b.WriteString(indent + "}\n")
}

// msg builds the format string for an error message.
func msg(fn *models.Function, opt *Options, isError bool, goCmp bool, inFmt string, multiAndGot ...interface{}) string {
	prefix := msgPrefix(opt)
	name := fn.MsgName() + inFmt
	if isError {
		return prefix + name + " error = %v, wantErr %v"
	}
	suffix := " = %v, want %v"
	if goCmp {
		suffix = " = %v, want %v\\ndiff=%s"
	}
	if len(multiAndGot) == 2 && multiAndGot[0].(bool) {
		return prefix + name + " " + multiAndGot[1].(string) + suffix
	}
	return prefix + name + suffix
}

func callArgs(fn *models.Function) string {
	var parts []string
	for _, a := range fn.Args() {
		if a.Type.IsVariadic {
			parts = append(parts, "tt.args."+a.Name+"...")
			continue
		}
		parts = append(parts, "tt.args."+a.Name)
	}
	return strings.Join(parts, ", ")
}
