// Package output writes the generated test files.
package output

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/cweill/gotests/internal/models"
)

// Writer writes the rendered test files.
type Writer interface {
	io.Writer
}

// Options holds the options for rendering a test file.
type Options struct {
	WriteFiles bool
	Template   *template
}

type template struct {
	Funcs []string
	// Needed imports that are not derived from the package.
	Extra []*models.Import
}

// Process renders the test file for pkg and writes it to w or to the test file
// of path.
func Process(w io.Writer, pkg *models.Package, path string, funcs []string, extra []*models.Import) error {
	content, err := render(pkg, path, funcs, extra)
	if err != nil {
		return err
	}
	if w != nil {
		fmt.Fprint(w, content)
		return nil
	}
	testPath := testFileFor(path)
	if err := os.WriteFile(testPath, []byte(content), 0666); err != nil {
		return err
	}
	return nil
}

func testFileFor(path string) string {
	if strings.HasSuffix(path, "_test.go") {
		return path
	}
	return strings.TrimSuffix(path, ".go") + "_test.go"
}

// render builds the content of the test file.
func render(pkg *models.Package, path string, funcs []string, extra []*models.Import) (string, error) {
	var header string
	var body string
	testPath := testFileFor(path)
	if strings.HasSuffix(path, "_test.go") {
		header = "package " + pkg.Name + "\n"
		body = "\n" + strings.Join(funcs, "")
	} else if data, err := os.ReadFile(testPath); err == nil {
		header, body = splitHeader(string(data))
		body += "\n" + strings.Join(funcs, "")
	} else {
		header = "package " + pkg.Name + "\n\n\n"
		body = "\n" + strings.Join(funcs, "")
	}
	// Determine the imports that the rendered file needs.
	needed := map[string]*models.Import{}
	add := func(i *models.Import) {
		needed[i.Name+"\x00"+i.Path] = i
	}
	for _, e := range extra {
		add(e)
	}
	if len(funcs) > 0 {
		add(&models.Import{Name: "testing", Path: "testing"})
	}
	// Collect the package qualifiers used in the rendered file.
	probe := header + "\n" + body
	for _, q := range qualifiers(probe) {
		if imp := lookup(pkg, q); imp != nil {
			add(imp)
		}
	}
	var list []*models.Import
	for _, i := range needed {
		list = append(list, i)
	}
	sort.Slice(list, func(a, b int) bool { return list[a].Path < list[b].Path })
	for _, imp := range pkg.Imports {
		if _, ok := needed[imp.Name+"\x00"+imp.Path]; ok {
			list = append(list, imp)
		}
	}
	block := importBlock(list)
	content := header + block + body
	return process(content, testPath)
}

// splitHeader splits the source into the part before the first declaration and
// the declarations themselves, without the import block.
func splitHeader(src string) (string, string) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "src.go", src, parser.ParseComments)
	if err != nil {
		// Fall back to a simple text based split.
		return src, ""
	}
	lines := strings.Split(src, "\n")
	pkgEnd := fset.Position(f.Package).Line
	var b strings.Builder
	for i := 0; i < pkgEnd; i++ {
		b.WriteString(lines[i] + "\n")
	}
	header := b.String()
	// Remove import declarations from the rest.
	var decls strings.Builder
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			continue
		}
		start := fset.Position(d.Pos()).Line
		end := fset.Position(d.End()).Line
		for i := start - 1; i < end; i++ {
			if i < len(lines) {
				decls.WriteString(lines[i] + "\n")
			}
		}
		decls.WriteString("\n")
	}
	return header, decls.String()
}

// importBlock renders the import declarations.
func importBlock(list []*models.Import) string {
	if len(list) == 0 {
		return ""
	}
	if len(list) == 1 {
		return "\nimport " + spec(list[0]) + "\n"
	}
	// Split into two groups: paths without a dot first.
	var first, second []*models.Import
	for _, i := range list {
		if strings.Contains(i.Path, ".") {
			second = append(second, i)
		} else {
			first = append(first, i)
		}
	}
	sort.Slice(first, func(a, b int) bool { return first[a].Path < first[b].Path })
	sort.Slice(second, func(a, b int) bool { return second[a].Path < second[b].Path })
	var b strings.Builder
	b.WriteString("\nimport (\n")
	for _, i := range first {
		b.WriteString("\t" + spec(i) + "\n")
	}
	if len(second) > 0 {
		b.WriteString("\n")
		for _, i := range second {
			b.WriteString("\t" + spec(i) + "\n")
		}
	}
	b.WriteString(")\n")
	return b.String()
}

func spec(i *models.Import) string {
	if i.Name != "" && i.Name != models.NameOf(i.Path) {
		return i.Name + " " + strconv.Quote(i.Path)
	}
	return strconv.Quote(i.Path)
}

// lookup resolves a package qualifier to an import.
func lookup(pkg *models.Package, name string) *models.Import {
	for _, imp := range pkg.Imports {
		if imp.Name == name {
			return imp
		}
	}
	return nil
}

// qualifiers returns the package qualifiers used in the source.
func qualifiers(src string) []string {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "probe.go", src, 0)
	if err != nil {
		return nil
	}
	set := map[string]bool{}
	var out []string
	ast.Inspect(f, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		if !set[id.Name] {
			set[id.Name] = true
			out = append(out, id.Name)
		}
		return true
	})
	sort.Strings(out)
	return out
}

// process formats the source the way goimports would.
func process(src, name string) (string, error) {
	tmp, err := os.CreateTemp("", "gotests_*")
	if err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	tmpName := tmp.Name()
	tmp.Close()
	defer os.Remove(tmpName)
	if name != "" {
		tmpName = name
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, tmpName, src, parser.ParseComments)
	if err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, f); err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	return buf.String(), nil
}
GOEOF
