	for _, i := range first {
		b.WriteString("\t" + spec(i) + "\n")
	}
	if len(second) > 0 {
		b.WriteString("\n")
		for _, i := range second {
			b.WriteString("\t" + spec(i) + "\n")
		}
	}
	b.WriteString(")\n")
	return b.String()
}

func spec(i *models.Import) string {
	if i.Name != "" && i.Name != models.NameOf(i.Path) {
		return i.Name + " " + strconv.Quote(i.Path)
	}
	return strconv.Quote(i.Path)
}

// lookup resolves a package qualifier to an import.
func lookup(pkg *models.Package, name string) *models.Import {
	for _, imp := range pkg.Imports {
		if imp.Name == name {
			return imp
		}
	}
	return nil
}

// qualifiers returns the package qualifiers used in the source.
func qualifiers(src string) []string {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "probe.go", src, 0)
	if err != nil {
		return nil
	}
	set := map[string]bool{}
	var out []string
	ast.Inspect(f, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		if !set[id.Name] {
			set[id.Name] = true
			out = append(out, id.Name)
		}
		return true
	})
	sort.Strings(out)
	return out
}

// process formats the source the way goimports would.
func process(src, name string) (string, error) {
	tmp, err := os.CreateTemp("", "gotests_*")
	if err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	tmpName := tmp.Name()
	tmp.Close()
	defer os.Remove(tmpName)
	if name != "" {
		tmpName = name
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, tmpName, src, parser.ParseComments)
	if err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, f); err != nil {
		return "", fmt.Errorf("output.Process: imports.Process: %v", err)
	}
	return buf.String(), nil
}
