		}
		if f.exclRegexp != nil && f.exclRegexp.MatchString(name) {
			continue
		}
		if f.exported && !fn.IsExported {
			continue
		}
		if f.onlyRegexp != nil && !f.onlyRegexp.MatchString(fn.Name) && !f.onlyRegexp.MatchString(name) {
			continue
		}
		if !f.all && f.onlyRegexp == nil && f.exclRegexp == nil && !f.exported {
