func capitalize(s string) string {
	if s == "" {
		return s
	}
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

// renderExtraImports returns the imports that the test functions need but that
// are not part of the package.
func renderExtraImports(fn *models.Function, opt *render.Options) []*models.Import {
	var out []*models.Import
	for _, w := range fn.Writers() {
		out = append(out, &models.Import{Name: "bytes", Path: "bytes"})
		break
	}
	if opt.UseGoCmp {
		for _, r := range fn.Results {
			if !models.IsBasicType(r.Type) {
				out = append(out, &models.Import{Name: "cmp", Path: "github.com/google/go-cmp/cmp"})
				break
			}
		}
	}
	if opt.Template != nil {
		if t := opt.Template.Lookup("function"); t != nil {
			out = append(out, &models.Import{Name: "assert", Path: "github.com/stretchr/testify/assert"})
		}
	}
	reflect := false
	for _, r := range fn.Results {
		if !models.IsBasicType(r.Type) {
			reflect = true
		}
	}
	if reflect {
		out = append(out, &models.Import{Name: "reflect", Path: "reflect"})
	}
	return out
}
