		inputs   = flag.Bool("i", false, "print test inputs in error messages")
		nosub    = flag.Bool("nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
		parallel = flag.Bool("parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
		named    = flag.Bool("named", false, "switch table tests from using slice to map (with test name for the key)")
		useCmp   = flag.Bool("use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
		template = flag.String("template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
		dir      = flag.String("template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
		params   = flag.String("template_params", "", "read external parameters to template by json with stdin")
		pfile    = flag.String("template_params_file", "", "read external parameters to template by json with file")
		aiFlag   = flag.Bool("ai", false, "generate test cases using AI (requires Ollama)")
		aiModel  = flag.String("ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
