	f.all = *all
	f.writeFiles = *write
	f.printInputs = *inputs
	f.subtests = !*nosub
	f.parallel = *parallel
	f.named = *named
	f.useGoCmp = *useCmp
	f.template = *template
	f.templateDir = *dir
	f.templateParams = *params
	f.paramsFile = *pfile
	f.ai = *aiFlag
	f.aiModel = *aiModel
	f.aiEndpoint = *aiEndp
	f.aiMinCases = *aiMin
	f.aiMaxCases = *aiMax
	if v, ok := os.LookupEnv("GOTESTS_TEMPLATE"); ok && f.template == "" {
		f.template = v
	}
	if v, ok := os.LookupEnv("GOTESTS_TEMPLATE_DIR"); ok && f.templateDir == "" {
		f.templateDir = v
