	var tmpl *template.Template
	if f.templateDir != "" {
		t, err := loadDir(f.templateDir)
		if err != nil {
			fmt.Printf("output.Process: loading custom templates: %v\n", err)
			return
		}
		tmpl = t
	} else if f.template != "" {
		t, err := loadNamed(f.template)
		if err != nil {
			fmt.Printf("output.Process: loading custom templates of name: %v\n", err)
			return
		}
		tmpl = t
	}
	var params map[string]interface{}
	if f.templateParams != "" {
		if err := json.Unmarshal([]byte(f.templateParams), &params); err != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", err)
			return
		}
	}
	if f.paramsFile != "" {
		data, err := os.ReadFile(f.paramsFile)
		if err != nil {
			fmt.Printf("Failed to read from %s ,err %v", f.paramsFile, err)
			return
