		client = ai.NewClient(ai.Config{
			Endpoint: f.aiEndpoint,
			Model:    f.aiModel,
			MinCases: f.aiMinCases,
			MaxCases: f.aiMaxCases,
		})
		ok, err := client.Available()
		if err != nil || !ok {
			fmt.Printf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s\n", f.aiEndpoint)
			return
		}
	}
	for _, path := range files {
		pkg, err := parser.Parse(path)
		if err != nil {
			fmt.Println(err)
			fmt.Println()
			continue
