		funcs := filter(pkg.Functions, f, pkg.TestFuncs)
		if len(funcs) == 0 {
			fmt.Printf("No tests generated for %s\n", path)
			continue
		}
		var texts []string
		var extra []*models.Import
		for _, fn := range funcs {
			var cases []*ai.TestCase
			if client != nil {
				resp, err := client.Generate(fn, ai.Scaffold(fn))
				if err != nil {
					fmt.Printf("Warning: failed to generate AI test cases for %s: %v\n", fn.Name, err)
				} else if parsed, perr := ai.ParseCases(resp); perr == nil {
					cases = parsed
				}
			}
			ropt := &render.Options{
				PrintInputs: f.printInputs,
				Subtests:    f.subtests,
				Parallel:    f.parallel,
				Named:       f.named,
				UseGoCmp:    f.useGoCmp,
				Template:    tmpl,
			}
			extra = append(extra, renderExtraImports(fn, ropt)...)
			text, err := render.TestFunction(fn, ropt, cases, params)
			if err != nil {
				fmt.Println(err)
				fmt.Println()
				continue
			}
			fmt.Printf("Generated Test%s\n", fn.TestName()[4:])
			texts = append(texts, text)
		}
		var w io.Writer
		if !f.writeFiles {
			w = os.Stdout
		}
		if err := output.Process(w, pkg, path, texts, extra); err != nil {
			fmt.Printf("output.Process: %v\n", err)
			fmt.Println()
			continue
		}
	}
}

// filter returns the functions that match the given flags.
func filter(funcs []*models.Function, f *flags, tests map[string]bool) []*models.Function {
	var out []*models.Function
	for _, fn := range funcs {
		name := fn.Name
		if fn.Receiver != nil {
			name = fn.Receiver.Field.Type.Value + capitalize(fn.Name)
		}
		if f.exclRegexp != nil && f.exclRegexp.MatchString(name) {
			continue
		}
		if f.exported && !fn.IsExported {
			continue
		}
		if f.onlyRegexp != nil && !f.onlyRegexp.MatchString(fn.Name) && !f.onlyRegexp.MatchString(name) {
			continue
		}
		if !f.all && f.onlyRegexp == nil && f.exclRegexp == nil && !f.exported {
			continue
		}
		if tests[fn.TestName()] {
			continue
		}
		out = append(out, fn)
	}
	return out
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

