	if opt.Template != nil {
		if t := opt.Template.Lookup("function"); t != nil {
			out = append(out, &models.Import{Name: "assert", Path: "github.com/stretchr/testify/assert"})
		}
	}
	reflect := false
	for _, r := range fn.Results {
		if !models.IsBasicType(r.Type) {
			reflect = true
		}
	}
	if reflect {
		out = append(out, &models.Import{Name: "reflect", Path: "reflect"})
	}
	return out
}
