cd /workspace && cat >> internal/models/models.go <<'GOEOF'

// MsgFormat returns the format string used for error messages.
func (f *Function) MsgFormat(subtests bool) string {
	prefix := ""
	if !subtests {
		prefix = "%q. "
	}
	inputs := ""
	if len(f.Parameters) > 0 {
		parts := make([]string, len(f.Parameters))
		for i := range parts {
			parts[i] = "%v"
		}
		inputs = "(" + strings.Join(parts, ", ") + ")"
	}
	return prefix + f.MsgName() + inputs
}

// MsgArgs returns the arguments used for the error message.
func (f *Function) MsgArgs(subtests bool) []string {
	var out []string
	if !subtests {
		out = append(out, "tt.name")
	}
	for _, p := range f.Parameters {
		out = append(out, "tt.args."+p.Name)
	}
	return out
}

// WriterField returns the name of the "want" field for an io.Writer parameter.
func (f *Function) WriterField(w *Field) string { return "want" + capitalize(w.Name) }

// WriterGot returns the variable name used for the output of an io.Writer
// parameter.
func (f *Function) WriterGot(w *Field) string { return "got" + capitalize(w.Name) }
GOEOF
mkdir -p internal/render/templates/testify && cat > internal/render/templates/testify/tests.go.tmpl <<'GOEOF'
