{{- if .Parallel}}
	t.Parallel()
{{- end}}
{{- if .ReceiverFields}}
	type fields struct {
{{- range .ReceiverFields}}
		{{.Name}} {{$.ArgValue .Type}}
{{- end}}
	}
{{- end}}
{{- if .Args}}
	type args struct {
{{- range .Args}}
		{{.Name}} {{$.ArgValue .Type}}
{{- end}}
	}
{{- end}}
	tests := {{if .Named}}map[string]struct {{"{"}}{{else}}[]struct {{"{"}}{{end}}
{{- if not .Named}}
		name string
{{- end}}
{{- if and .Receiver .ReceiverStructField}}
		{{.ReceiverVar}} {{.ReceiverType}}
{{- end}}
{{- if .NeedsConstructor}}
		fields fields
{{- end}}
{{- if .Args}}
		args args
{{- end}}
{{- range $i, $r := .TestResults}}
		{{$.WantName $i}} {{$.ArgValue $r.Type}}
{{- end}}
{{- range .Writers}}
		{{$.WriterField .}} string
{{- end}}
{{- if .ReturnsError}}
		assertion assert.ErrorAssertionFunc
{{- end}}
	}{
