)

//go:embed templates
var templatesFS embed.FS

// LoadNamed loads the built-in templates with the given name.
func LoadNamed(name string) (*template.Template, error) {
	sub, err := fs.Sub(templatesFS, "templates/"+name)
	if err != nil {
		return nil, fmt.Errorf("templates.ParseFS: %v", err)
	}
	t, err := template.ParseFS(sub, "*.tmpl")
	if err != nil {
		return nil, fmt.Errorf("templates.ParseFS: %v", err)
	}
	return t, nil
}

// LoadDir loads the custom templates from the given directory.
func LoadDir(dir string) (*template.Template, error) {
	var files []string
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("tmpls.ParseFiles: %v", err)
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		files = append(files, filepath.Join(dir, e.Name()))
	}
	t, err := template.ParseFiles(files...)
	if err != nil {
		return nil, fmt.Errorf("tmpls.ParseFiles: %v", err)
	}
	return t, nil
}
