package main

import (
	"fmt"
	"os"

	"github.com/cweill/gotests/internal/parser"
)

func main() {
	paths := os.Args[1:]
	for _, p := range paths {
		pkg, err := parser.Parse(p)
		if err != nil {
			fmt.Println("ERR", err)
			continue
		}
		for _, fn := range pkg.Functions {
			fmt.Printf("N=%s tp=", fn.Name)
			for _, tp := range fn.TypeParams {
				fmt.Printf("[%s:%s]", tp.Name, tp.Constraint)
			}
			fmt.Printf(" recv=")
			if fn.Receiver != nil {
				fmt.Printf("[%s v=%q star=%v u=%q fields=%d]", fn.Receiver.Field.Name, fn.Receiver.Field.Type.Value, fn.Receiver.Field.Type.IsStar, fn.Receiver.Field.Type.Underlying, len(fn.Receiver.Fields))
			}
			fmt.Printf(" results=")
			for _, r := range fn.Results {
				fmt.Printf("[%s v=%q u=%q]", r.Name, r.Type.Value, r.Type.Underlying)
			}
			fmt.Printf(" params=")
			for _, pa := range fn.Parameters {
				fmt.Printf("[%s v=%q var=%v]", pa.Name, pa.Type.Value, pa.Type.IsVariadic)
			}
			fmt.Println()
		}
	}
}
