{"command": "cd /workspace && cat > internal/render/render.go <<'GOEOF'
// Package render turns function models into Go test functions.
package render

import (
	"fmt"
	"strings"
	"text/template"
	"unicode"
	"unicode/utf8"

	"github.com/cweill/gotests/internal/ai"
	"github.com/cweill/gotests/internal/models"
)

// Options holds the options that influence how a test function is rendered.
type Options struct {
	PrintInputs bool
	Subtests    bool
	Parallel    bool
	Named       bool
	UseGoCmp    bool
	Template    interface{}
}

// capitalize upper-cases the first letter of a string.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

// data is the structure passed to custom test templates.
type data struct {
	*models.Function
	PrintInputs      bool
	Subtests         bool
	Parallel         bool
	Named            bool
	UseGoCmp         bool
	TemplateParams   map[string]interface{}
	AIGeneratedCases []interface{}
}

// TestFunction renders a single test function for fn.
func TestFunction(fn *models.Function, opt *Options, cases []*ai.TestCase, params map[string]interface{}) (string, error) {
	if tt, ok := opt.Template.(interface{ Lookup(string) *template.Template }); ok {
		if t := tt.Lookup("function"); t != nil {
			var b strings.Builder
			d := &data{
				Function:         fn,
				PrintInputs:      opt.PrintInputs,
				Subtests:         opt.Subtests,
				Parallel:         opt.Parallel,
				Named:            opt.Named,
				UseGoCmp:         opt.UseGoCmp,
				TemplateParams:   params,
				AIGeneratedCases: aiCases(cases),
			}
			if err := t.Execute(&b, d); err != nil {
				return "", fmt.Errorf("render.TestFunction: %v", err)
			}
			return b.String(), nil
		}
	}
	var b strings.Builder
	writeTestFunction(&b, fn, opt, cases)
	return b.String(), nil
}

func aiCases(cases []*ai.TestCase) []interface{} {
	var out []interface{}
	for _, c := range cases {
		out = append(out, c)
	}
	return out
}

func writeTestFunction(b *strings.Builder, fn *models.Function, opt *Options, cases []*ai.TestCase) {
	fmt.Fprintf(b, "func %s(t *testing.T) {\n", fn.TestName())
	if opt.Parallel {
		b.WriteString("\tt.Parallel()\n")
	}
	if fields := fn.ReceiverFields(); len(fields) > 0 {
		b.WriteString("\ttype fields struct {\n")
		for _, f := range fields {
			fmt.Fprintf(b, "\t\t%s %s\n", f.Name, fn.TypeText(f.Type))
		}
		b.WriteString("\t}\n")
	}
	args := fn.Args()
	if len(args) > 0 {
		b.WriteString("\ttype args struct {\n")
		for _, a := range args {
			fmt.Fprintf(b, "\t\t%s %s\n", a.Name, fn.TypeText(a.Type))
		}
		b.WriteString("\t}\n")
	}
	if opt.Named {
		b.WriteString("\ttests := map[string]struct {\n")
	} else {
		b.WriteString("\ttests := []struct {\n")
	}
	if !opt.Named {
		b.WriteString("\t\tname string\n")
	}
	if fn.Receiver != nil && fn.ReceiverStructField() {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.ReceiverVar(), fn.ReceiverType())
	}
	if len(fn.ReceiverFields()) > 0 {
		b.WriteString("\t\tfields fields\n")
	}
	if len(args) > 0 {
		b.WriteString("\t\targs args\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.WantName(i), fn.TypeText(fn.Results[i].Type))
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "\t\t%s string\n", fn.WriterField(w))
	}
	if fn.ReturnsError {
		b.WriteString("\t\twantErr bool\n")
	}
	b.WriteString("\t}{\n")
	if len(cases) > 0 {
		for _, l := range ai.CasesBlock(fn, cases) {
			b.WriteString(l)
		}
	} else {
		b.WriteString("\t\t// TODO: Add test cases.\n")
	}
	b.WriteString("\t}\n")
	if opt.Named {
		b.WriteString("\tfor name, tt := range tests {\n")
	} else {
		b.WriteString("\tfor _, tt := range tests {\n")
	}
	if opt.Subtests {
		if opt.Named {
			b.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			b.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opt.Parallel {
			b.WriteString("\t\t\tt.Parallel()\n")
		}
	}
	writeTestBody(b, fn, opt)
	if opt.Subtests {
		b.WriteString("\t\t})\n")
	}
	b.WriteString("\t}\n}\n")
}

// writeTestBody writes the body of the subtest (or of the loop body when
// subtests are disabled).
func writeTestBody(b *strings.Builder, fn *models.Function, opt *Options) {
	indent := "\t\t"
	if opt.Subtests {
		indent = "\t\t\t"
	}
	if fn.NeedsConstructor() {
		fmt.Fprintf(b, "%s%s := %s{\n", indent, fn.ReceiverVar(), fn.ConstructorType())
		for _, f := range fn.ReceiverFields() {
			fmt.Fprintf(b, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
		}
		fmt.Fprintf(b, "%s}\n", indent)
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "%s%s := &bytes.Buffer{}\n", indent, w.Name)
	}
	call := fn.Call()
	results := fn.Results
	switch {
	case fn.ReturnsError && len(results) == 0:
