		b.WriteString("\t}\n")
	}
	if opt.Named {
		b.WriteString("\ttests := map[string]struct {\n")
	} else {
		b.WriteString("\ttests := []struct {\n")
	}
	if !opt.Named {
		b.WriteString("\t\tname string\n")
	}
	if fn.Receiver != nil && fn.ReceiverStructField() {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.ReceiverVar(), fn.ReceiverType())
	}
	if len(fn.ReceiverFields()) > 0 {
		b.WriteString("\t\tfields fields\n")
	}
	if len(args) > 0 {
		b.WriteString("\t\targs args\n")
	}
	for i := range fn.Results {
		fmt.Fprintf(b, "\t\t%s %s\n", fn.WantName(i), fn.TypeText(fn.Results[i].Type))
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "\t\t%s string\n", fn.WriterField(w))
	}
	if fn.ReturnsError {
		b.WriteString("\t\twantErr bool\n")
	}
	b.WriteString("\t}{\n")
	if len(cases) > 0 {
		for _, l := range ai.CasesBlock(fn, cases) {
			b.WriteString(l)
		}
	} else {
		b.WriteString("\t\t// TODO: Add test cases.\n")
	}
	b.WriteString("\t}\n")
	if opt.Named {
		b.WriteString("\tfor name, tt := range tests {\n")
	} else {
		b.WriteString("\tfor _, tt := range tests {\n")
	}
	if opt.Subtests {
		if opt.Named {
			b.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			b.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opt.Parallel {
			b.WriteString("\t\t\tt.Parallel()\n")
		}
	}
	writeTestBody(b, fn, opt)
	if opt.Subtests {
		b.WriteString("\t\t})\n")
	}
	b.WriteString("\t}\n}\n")
}

// writeTestBody writes the body of the subtest (or of the loop body when
// subtests are disabled).
func writeTestBody(b *strings.Builder, fn *models.Function, opt *Options) {
	indent := "\t\t"
	if opt.Subtests {
		indent = "\t\t\t"
	}
	if fn.NeedsConstructor() {
		fmt.Fprintf(b, "%s%s := %s{\n", indent, fn.ReceiverVar(), fn.ConstructorType())
		for _, f := range fn.ReceiverFields() {
			fmt.Fprintf(b, "%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name)
		}
		fmt.Fprintf(b, "%s}\n", indent)
	}
	for _, w := range fn.Writers() {
		fmt.Fprintf(b, "%s%s := &bytes.Buffer{}\n", indent, w.Name)
	}
	call := fn.Call()
	results := fn.Results
	switch {
	case fn.ReturnsError && len(results) == 0:
		fmt.Fprintf(b, "%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call)
		f, a := msgInfo(fn, opt, "err")
		fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList(a, "err", "tt.wantErr"))
		b.WriteString(indent + "}\n")
	case len(results) == 1 && !fn.ReturnsError:
		got := gotVar(results[0], 0)
		want := fn.WantName(0)
		if models.IsBasicType(results[0].Type) {
			fmt.Fprintf(b, "%sif %s := %s; %s != tt.%s {\n", indent, got, call, got, want)
			f, a := msgInfo(fn, opt, "plain")
			fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList2(a, got, want))
			b.WriteString(indent + "}\n")
			break
		}
		if opt.UseGoCmp {
			fmt.Fprintf(b, "%sif %s := %s; !cmp.Equal(tt.%s, %s) {\n", indent, got, call, want, got)
			f, a := msgInfo(fn, opt, "cmp")
			fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList3(a, got, want, want, got))
			b.WriteString(indent + "}\n")
			break
		}
		fmt.Fprintf(b, "%sif %s := %s; !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, call, got, want)
		f, a := msgInfo(fn, opt, "plain")
		fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList2(a, got, want))
		b.WriteString(indent + "}\n")
	case len(results) == 0:
		fmt.Fprintf(b, "%s%s\n", indent, call)
	default:
		fmt.Fprintf(b, "%s%s := %s\n", indent, fn.GotVars(), call)
		if fn.ReturnsError {
			if opt.Subtests {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				f, a := msgInfo(fn, opt, "err")
				fmt.Fprintf(b, "%s\tt.Fatalf(%q%s)\n", indent, f, argList(a, "err", "tt.wantErr"))
				b.WriteString(indent + "}\n")
			} else {
				fmt.Fprintf(b, "%sif (err != nil) != tt.wantErr {\n", indent)
				f, a := msgInfo(fn, opt, "err")
				fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList(a, "err", "tt.wantErr"))
				b.WriteString(indent + "\tcontinue\n")
				b.WriteString(indent + "}\n")
			}
			b.WriteString(indent + "if tt.wantErr {\n")
			b.WriteString(indent + "\treturn\n")
			b.WriteString(indent + "}\n")
		}
		for i := range results {
			got := gotVar(results[i], i)
			want := fn.WantName(i)
			if models.IsBasicType(results[i].Type) {
				fmt.Fprintf(b, "%sif %s != tt.%s {\n", indent, got, want)
				f, a := msgInfo(fn, opt, "plain")
				fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList3(a, got, want, got, want))
				b.WriteString(indent + "}\n")
				continue
			}
			if opt.UseGoCmp {
				fmt.Fprintf(b, "%sif !cmp.Equal(tt.%s, %s) {\n", indent, want, got)
				f, a := msgInfo(fn, opt, "cmp")
				fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList5(a, got, want, want, got))
				b.WriteString(indent + "}\n")
				continue
			}
			fmt.Fprintf(b, "%sif !reflect.DeepEqual(%s, tt.%s) {\n", indent, got, want)
			f, a := msgInfo(fn, opt, "plain")
			fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList3(a, got, want, got, want))
			b.WriteString(indent + "}\n")
		}
	}
	for _, w := range fn.Writers() {
		got := fn.WriterGot(w)
		want := fn.WriterField(w)
		fmt.Fprintf(b, "%sif %s := %s.String(); %s != tt.%s {\n", indent, got, w.Name, got, want)
		f, a := msgInfo(fn, opt, "plain")
		fmt.Fprintf(b, "%s\tt.Errorf(%q%s)\n", indent, f, argList2(a, got, want))
		b.WriteString(indent + "}\n")
	}
}

// msgInfo returns the format string and the leading arguments of the error
// messages.  kind is one of "err", "cmp", "got" or "plain".
func msgInfo(fn *models.Function, opt *Options, kind string) (string, []string) {
	var args []string
	prefix := ""
	if !opt.Subtests {
		prefix = "%q. "
		args = append(args, "tt.name")
	}
	inputs := ""
	if opt.PrintInputs && len(fn.Parameters) > 0 {
		var parts []string
		for range fn.Parameters {
			parts = append(parts, "%v")
		}
		inputs = "(" + strings.Join(parts, ", ") + ")"
		for _, p := range fn.Parameters {
			args = append(args, "tt.args."+p.Name)
		}
	}
	name := prefix + fn.MsgName() + "()" + inputs
	switch kind {
	case "err":
		return name + " error = %v, wantErr %v", args
	case "cmp":
		return name + " = %v, want %v\\ndiff=%s", args
	case "got":
		return name + " %v = %v, want %v", args
	default:
		return name + " = %v, want %v", args
	}
}

func argList(args []string, extra ...string) string {
	all := append(append([]string{}, args...), extra...)
	return ", " + strings.Join(all, ", ")
}

func argList2(args []string, a1, a2 string) string {
	return argList(args, a1, a2)
}

func argList3(args []string, a1, a2, a3, a4 string) string {
	return argList(args, a1, a2, a3, a4)
}

func argList5(args []string, a1, a2, a3, a4 string) string {
	return argList(args, a1, a2, a3, a4)
}

func gotVar(r *models.Field, i int) string {
	if r.Name != "" {
		return "got" + capitalize(r.Name)
	}
	if i == 0 {
		return "got"
	}
	return fmt.Sprintf("got%d", i)
}
